window.INSCRIPTION_DATA = {"records":[{"id":"hoyland-2011-4","name":"Hoyland 2011, no. 4","siglum":"Hoyland 2011, no. 4","religion":"jewish","dateLabel":"Third–fifth century CE?","dateNote":"No explicit date. Assigned on palaeographic and contextual grounds; the range is deliberately wide and uncertain.","language":"Nabataean Aramaic","script":"Nabataean Aramaic","locality":"Hegra & al-ʿUlā","site":"Madāʾin Ṣāliḥ (Hegra)","modernCountry":"Saudi Arabia","lat":26.7917,"lon":37.9542,"geoPrecision":"approximate","material":"Sandstone","support":"Rock face","dimensions":null,"transliteration":null,"translation":"May Jacob son of Samuel be remembered well.","provenance":"Jewish · north-west Arabia (Saudi Arabia)","synopsis":"A short Nabataean Aramaic graffito of the common 'may X be remembered' type. The Jewish identification rests entirely on the names: Jacob (Yaʿqūb) and Samuel (Shemuʾel) are distinctively Jewish in this region and period. Robert Hoyland gathered this and related texts to argue that a Jewish presence in the Ḥijāz is epigraphically visible well before Islam, matching what later Muslim sources say about Jewish communities at Medina, Khaybar and elsewhere.","textCount":1,"inLindstedt":true,"additionReason":null,"references":[{"citation":"Hoyland, Robert G. \"The Jews of the Hijaz in the Qurʾān and in Their Inscriptions.\" In New Perspectives on the Qurʾān, edited by Gabriel S. Reynolds, 91–116. London: Routledge, 2011 (at 94–95).","url":null},{"citation":"Lindstedt, Ilkka. \"A Map and List of the Monotheistic Inscriptions of Arabia, 400–600 CE.\" Hadis ve Siyer Araştırmaları 10, no. 2 (2025): 275–283.","url":"https://www.hadithandsira.info/files/articles/dosya/10-2-7(1).pdf"},{"citation":"Lindstedt, Ilkka. Muḥammad and His Followers in Context: The Religious Map of Late Antique Arabia. Leiden: Brill, 2024.","url":"https://doi.org/10.1163/9789004687134"}],"scriptFacets":["Nabataean Aramaic"],"materialFacet":"Sandstone"},{"id":"hoyland-2011-16","name":"Hoyland 2011, no. 16","siglum":"Hoyland 2011, no. 16","religion":"jewish","dateLabel":"Third–fifth century CE?","dateNote":"No explicit date. Assigned on palaeographic and contextual grounds.","language":"Nabataean Aramaic","script":"Nabataean Aramaic","locality":"Hegra & al-ʿUlā","site":"Madāʾin Ṣāliḥ (Hegra)","modernCountry":"Saudi Arabia","lat":26.8005,"lon":37.9695,"geoPrecision":"approximate","material":"Sandstone","support":"Rock face","dimensions":null,"transliteration":null,"translation":"Indeed, may Simon son of ʿAdī-w be remembered.","provenance":"Jewish · north-west Arabia (Saudi Arabia)","synopsis":"Another brief memorial graffito from the Hegra area. 'Simon' (Shimʿon) is the Jewish marker here; the patronym ʿAdī-w is a thoroughly Arabian name carrying the Nabataean final -w (so-called wawation). The combination is typical of the region: Jewish families using both biblical and local Arabian names, writing in the Aramaic script that served north-west Arabia for centuries.","textCount":1,"inLindstedt":true,"additionReason":null,"references":[{"citation":"Hoyland, Robert G. \"The Jews of the Hijaz in the Qurʾān and in Their Inscriptions.\" In New Perspectives on the Qurʾān, edited by Gabriel S. Reynolds, 91–116. London: Routledge, 2011 (at 99).","url":null},{"citation":"Lindstedt, Ilkka. \"A Map and List of the Monotheistic Inscriptions of Arabia, 400–600 CE.\" Hadis ve Siyer Araştırmaları 10, no. 2 (2025): 275–283.","url":"https://www.hadithandsira.info/files/articles/dosya/10-2-7(1).pdf"},{"citation":"Nehmé, Laïla, ed. The Digital Corpus of the Nabataean and Developing Arabic Inscriptions (DiCoNab). 2024–.","url":"https://diconab.huma-num.fr/"}],"scriptFacets":["Nabataean Aramaic"],"materialFacet":"Sandstone"},{"id":"hoyland-2011-17","name":"Hoyland 2011, no. 17","siglum":"Hoyland 2011, no. 17","religion":"jewish","dateLabel":"Third–fifth century CE?","dateNote":"No explicit date. Assigned on palaeographic and contextual grounds.","language":"Nabataean Aramaic","script":"Nabataean Aramaic","locality":"Hegra & al-ʿUlā","site":"Al-ʿUlā","modernCountry":"Saudi Arabia","lat":26.6167,"lon":37.9167,"geoPrecision":"approximate","material":"Sandstone","support":"Rock face","dimensions":null,"transliteration":null,"translation":"May Laḥmu son of Yehūdā be remembered well.","provenance":"Jewish · north-west Arabia (Saudi Arabia)","synopsis":"A memorial graffito from the oasis of al-ʿUlā (ancient Dadan), the other major settlement of the Ḥijāzī caravan corridor alongside Hegra. The father's name Yehūdā (Judah) is unambiguously Jewish. Texts like this one are the reason scholars treat the north-west Arabian oases as having had a settled, literate Jewish population in late antiquity rather than only occasional Jewish visitors.","textCount":1,"inLindstedt":true,"additionReason":null,"references":[{"citation":"Hoyland, Robert G. \"The Jews of the Hijaz in the Qurʾān and in Their Inscriptions.\" In New Perspectives on the Qurʾān, edited by Gabriel S. Reynolds, 91–116. London: Routledge, 2011 (at 100).","url":null},{"citation":"Lindstedt, Ilkka. \"A Map and List of the Monotheistic Inscriptions of Arabia, 400–600 CE.\" Hadis ve Siyer Araştırmaları 10, no. 2 (2025): 275–283.","url":"https://www.hadithandsira.info/files/articles/dosya/10-2-7(1).pdf"},{"citation":"Lindstedt, Ilkka. Muḥammad and His Followers in Context: The Religious Map of Late Antique Arabia. Leiden: Brill, 2024.","url":"https://doi.org/10.1163/9789004687134"}],"scriptFacets":["Nabataean Aramaic"],"materialFacet":"Sandstone"},{"id":"gatier-2020-7","name":"Gatier 2020, no. 7","siglum":"Gatier 2020, no. 7 (Mabrak al-Nāqa)","religion":"jewish","dateLabel":"Fourth–seventh century CE?","dateNote":"Undated. Greek graffiti at this site are assigned broadly to late antiquity on palaeographic grounds.","language":"Greek","script":"Greek","locality":"Hegra & al-ʿUlā","site":"Mabrak al-Nāqa, c. 17 km north of Hegra","modernCountry":"Saudi Arabia","lat":26.9405,"lon":37.9722,"geoPrecision":"approximate","material":"Sandstone","support":"Cliff face in a mountain pass","dimensions":null,"transliteration":null,"translation":"Isaac son of Benjamin.","provenance":"Jewish · north-west Arabia (Saudi Arabia)","synopsis":"A Greek graffito in the pass of Mabrak al-Nāqa, a natural bottleneck on the road north from Hegra where travellers stopped and carved their names. Pierre-Louis Gatier's edition identifies this one as Jewish purely from the names Isaac and Benjamin. Its significance is that it is in Greek: the Ḥijāz was not linguistically sealed off, and travellers moving between the Roman provinces and Arabia left traces in the language of the eastern Mediterranean.","textCount":1,"inLindstedt":true,"additionReason":null,"references":[{"citation":"Gatier, Pierre-Louis. \"Les graffites grecs de Mabrak an-Naqah (Arabie Saoudite).\" Cahiers du Centre Gustave Glotz 31 (2020): 111–130 (at 117).","url":null},{"citation":"Lindstedt, Ilkka. \"A Map and List of the Monotheistic Inscriptions of Arabia, 400–600 CE.\" Hadis ve Siyer Araştırmaları 10, no. 2 (2025): 275–283.","url":"https://www.hadithandsira.info/files/articles/dosya/10-2-7(1).pdf"}],"scriptFacets":["Greek"],"materialFacet":"Sandstone"},{"id":"ujadhda-405","name":"UJadhDA 405","siglum":"UJadhDA 405 (= ThMNN 619; ThNUJ 145; UJadh 405)","religion":"jewish","dateLabel":"Undated; possibly fifth century CE","dateNote":"No date in the text. Placed in the fifth century on script-development grounds (late Nabataean moving toward Arabic).","language":"Nabataean Aramaic","script":"Nabataeo-Arabic","locality":"Tabūk & Ḥismā","site":"Umm Jadhāyidh, on the Darb al-Bakrah caravan route (c. 125 km north-west of Hegra)","modernCountry":"Saudi Arabia","lat":27.65,"lon":36.85,"geoPrecision":"indicative","material":"Sandstone","support":"Rock face or large rock","dimensions":null,"transliteration":"dkyr / ḥny br / nḥmy","translation":"May Ḥunayy son of Nehemiah be remembered.","provenance":"Jewish · north-west Arabia (Saudi Arabia)","synopsis":"One of more than five hundred inscriptions recorded at Umm Jadhāyidh, a major stopping-place on the Darb al-Bakrah route between Hegra and Petra. The Jewish identification rests on the father's name, Nehemiah; the writer's own name may abbreviate the biblical Ḥōnī. The script is 'Nabataeo-Arabic', a transitional stage in which the Nabataean alphabet is visibly turning into the Arabic one, which is exactly why this corpus matters for the history of writing as well as of religion.","textCount":1,"inLindstedt":true,"additionReason":null,"references":[{"citation":"Nehmé, Laïla. \"UJadhDA 405.\" In DiCoNab: Digital Corpus of the Nabataean and Developing Arabic Inscriptions, edited by L. Nehmé, 2024.","url":"https://diconab.huma-num.fr/inscriptions/145"},{"citation":"Nehmé, Laïla, ed. The Darb al-Bakrah: A Caravan Route in North-West Arabia Discovered by Ali I. al-Ghabban. Catalogue of the Inscriptions. Riyadh: Saudi Commission for Tourism and National Heritage, 2018 (at 176).","url":null},{"citation":"Lindstedt, Ilkka. \"A Map and List of the Monotheistic Inscriptions of Arabia, 400–600 CE.\" Hadis ve Siyer Araştırmaları 10, no. 2 (2025): 275–283.","url":"https://www.hadithandsira.info/files/articles/dosya/10-2-7(1).pdf"}],"scriptFacets":["Nabataeo-Arabic"],"materialFacet":"Sandstone"},{"id":"fas-1","name":"FaS 1","siglum":"FaS 1 (= HRahDA 1)","religion":"jewish","dateLabel":"Undated; probably fifth or sixth century CE","dateNote":"No date in the text; assigned on palaeographic grounds.","language":"Old Arabic","script":"Paleo-Arabic","locality":"Tabūk & Ḥismā","site":"Wādī al-Misadd, Ḥarrat al-Rahā (between Tabūk and Hegra)","modernCountry":"Saudi Arabia","lat":27.85,"lon":37.25,"geoPrecision":"indicative","material":"Sandstone","support":"Rock face or large rock","dimensions":null,"transliteration":"bšr br smwʾl / ktbt ḏʾ ʾlktb","translation":"Bishr son of Samawʾal. I wrote this writing.","provenance":"Jewish · north-west Arabia (Saudi Arabia)","synopsis":"A Paleo-Arabic signature discovered by the Saudi exploration team Farīq aṣ-Ṣaḥrāʾ between Tabūk and al-Ḥijr. The father's name Samawʾal (Samuel) is the Jewish indicator, and it is a name with deep Arabian resonance, borne by the pre-Islamic Jewish poet-prince al-Samawʾal ibn ʿĀdiyāʾ, a byword for loyalty in Arabic literature. The text is a good example of what Lindstedt emphasises: ordinary people in fifth- and sixth-century Arabia could write, and did so in Arabic.","textCount":1,"inLindstedt":true,"additionReason":null,"references":[{"citation":"Nehmé, Laïla, and Abdullah al-Saeed. \"FaS 1.\" In DiCoNab: Digital Corpus of the Nabataean and Developing Arabic Inscriptions, edited by L. Nehmé, 2024.","url":"https://diconab.huma-num.fr/inscriptions/94"},{"citation":"Farīq aṣ-Ṣaḥrāʾ. \"Arabic Inscriptions in Nabataean Style\" (in Arabic). Alsahra.org, September 2017.","url":"https://alsahra.org/?p=17938"},{"citation":"Lindstedt, Ilkka. \"A Map and List of the Monotheistic Inscriptions of Arabia, 400–600 CE.\" Hadis ve Siyer Araştırmaları 10, no. 2 (2025): 275–283.","url":"https://www.hadithandsira.info/files/articles/dosya/10-2-7(1).pdf"}],"scriptFacets":["Paleo-Arabic"],"materialFacet":"Sandstone"},{"id":"gatier-2020-christian","name":"Gatier 2020: Greek Christian graffiti","siglum":"Gatier 2020, nos. 1–3, 10–11, 14–20","religion":"christian","dateLabel":"Fourth–seventh century CE?","dateNote":"Undated; assigned broadly to late antiquity on palaeographic and onomastic grounds.","language":"Greek","script":"Greek","locality":"Hegra & al-ʿUlā","site":"Mabrak al-Nāqa, c. 17 km north of Hegra","modernCountry":"Saudi Arabia","lat":26.9455,"lon":37.9805,"geoPrecision":"approximate","material":"Sandstone","support":"Cliff face in a mountain pass","dimensions":null,"transliteration":null,"translation":null,"provenance":"Christian · north-west Arabia (Saudi Arabia)","synopsis":"Of the twenty Greek graffiti Gatier recorded in this pass, at least twelve are certainly Christian: some carry crosses, others bear names drawn from the Apostles and widely venerated saints, or names that evoke a Christian idea. This single map symbol therefore stands for a whole cluster of texts. Taken together they show Christian travellers passing regularly through the Ḥijāz north of Hegra, a corridor linking Roman Arabia to the oases of the peninsula.","textCount":12,"inLindstedt":true,"additionReason":null,"references":[{"citation":"Gatier, Pierre-Louis. \"Les graffites grecs de Mabrak an-Naqah (Arabie Saoudite).\" Cahiers du Centre Gustave Glotz 31 (2020): 111–130 (at 127).","url":null},{"citation":"Lindstedt, Ilkka. \"A Map and List of the Monotheistic Inscriptions of Arabia, 400–600 CE.\" Hadis ve Siyer Araştırmaları 10, no. 2 (2025): 275–283.","url":"https://www.hadithandsira.info/files/articles/dosya/10-2-7(1).pdf"},{"citation":"Lindstedt, Ilkka. Muḥammad and His Followers in Context: The Religious Map of Late Antique Arabia. Leiden: Brill, 2024.","url":"https://doi.org/10.1163/9789004687134"}],"scriptFacets":["Greek"],"materialFacet":"Sandstone"},{"id":"bshda-2-3","name":"BShDA 2 and 3","siglum":"BShDA 2, BShDA 3","religion":"christian","dateLabel":"Undated; probably fifth or sixth century CE","dateNote":"No date in the text; assigned on palaeographic grounds.","language":"Nabataean Aramaic","script":"Paleo-Arabic","locality":"Najrān & Ḥimā","site":"Barqā al-Shāʿ (or Najid Saḥī), southern Saudi Arabia","modernCountry":"Saudi Arabia","lat":17.95,"lon":44.05,"geoPrecision":"indicative","material":"Sandstone","support":"Rock face or large rock","dimensions":null,"transliteration":"ḥmd{w} br / ʾb{w}mrʾh","translation":"Ḥamd son of Abū Marʾah.","provenance":"Christian · southern Saudi Arabia","synopsis":"Two signatures cut by the same man at the same site; BShDA 2 is accompanied by a large cross, which is what places the pair in the Christian column. The site identification is itself uncertain: the editors give it as either Barqā al-Shāʿ or Najid Saḥī, so this marker's position is only indicative. The texts came to scholarly attention through a photograph posted on social media in 2023, a good illustration of how fast and how informally this field now moves.","textCount":2,"inLindstedt":true,"additionReason":null,"references":[{"citation":"Nehmé, Laïla. \"BShDA 2.\" In DiCoNab: Digital Corpus of the Nabataean and Developing Arabic Inscriptions, edited by L. Nehmé, 2024.","url":"https://diconab.huma-num.fr/inscriptions/126"},{"citation":"Nehmé, Laïla. \"BShDA 3.\" In DiCoNab: Digital Corpus of the Nabataean and Developing Arabic Inscriptions, edited by L. Nehmé, 2024.","url":"https://diconab.huma-num.fr/inscriptions/129"},{"citation":"Lindstedt, Ilkka. \"A Map and List of the Monotheistic Inscriptions of Arabia, 400–600 CE.\" Hadis ve Siyer Araştırmaları 10, no. 2 (2025): 275–283.","url":"https://www.hadithandsira.info/files/articles/dosya/10-2-7(1).pdf"}],"scriptFacets":["Paleo-Arabic"],"materialFacet":"Sandstone"},{"id":"shthda-1","name":"ShThDA 1","siglum":"ShThDA 1","religion":"christian","dateLabel":"Undated; probably fifth or sixth century CE","dateNote":"No date in the text; the fifth–sixth century range follows the editors' palaeographic and onomastic assessment.","language":"Undetermined","script":"Paleo-Arabic","locality":"Tabūk & Ḥismā","site":"Shaʿīb al-Thamīlah, northern Saudi Arabia (not the toponym of the same name south of Riyadh)","modernCountry":"Saudi Arabia","lat":28.35,"lon":36.95,"geoPrecision":"indicative","material":"Basalt","support":"Rock face or large rock","dimensions":null,"transliteration":"ʾlḥdʾ br ṯʿlbh","translation":"Al-Ḥaddāʾ son of Thaʿlabah.","provenance":"Christian · northern Saudi Arabia","synopsis":"A personal name accompanied by a cross, cut into basalt, the volcanic rock that covers large tracts of northern Arabia. The cross is the only religious content, which is why the Christian label here (as with most of this category) is an inference rather than a statement the writer made. The text was found by chance in 2022 by an amateur explorer and passed to the epigraphist Laïla Nehmé, another sign of how much of this corpus arrives outside formal excavation.","textCount":1,"inLindstedt":true,"additionReason":null,"references":[{"citation":"Nehmé, Laïla. \"ShThDA 1.\" In DiCoNab: Digital Corpus of the Nabataean and Developing Arabic Inscriptions, edited by L. Nehmé, 2024.","url":"https://diconab.huma-num.fr/inscriptions/122"},{"citation":"Nehmé, Laïla. \"Bulletin épigraphique.\" Syria 101 (2024): 317.","url":null},{"citation":"Lindstedt, Ilkka. \"A Map and List of the Monotheistic Inscriptions of Arabia, 400–600 CE.\" Hadis ve Siyer Araştırmaları 10, no. 2 (2025): 275–283.","url":"https://www.hadithandsira.info/files/articles/dosya/10-2-7(1).pdf"}],"scriptFacets":["Paleo-Arabic"],"materialFacet":"Basalt"},{"id":"hsda-corpus","name":"HSDA corpus (Ḥimā Paleo-Arabic inscriptions)","siglum":"HSDA (Ḥimà-Sud PalAr, Ḥimà-Idhbāḥ PalAr, Ḥimà-al-Musammāt PalAr)","religion":"christian","dateLabel":"Undated; probably fifth and sixth century CE","dateNote":"Some texts in the group carry explicit dates (470 and 513 CE); the rest are placed alongside them on palaeographic grounds.","language":"Old Arabic (some with Nabataean Aramaic formulae)","script":"Paleo-Arabic","locality":"Najrān & Ḥimā","site":"Ḥimā (Biʾr Ḥimā), c. 90 km north of Najrān","modernCountry":"Saudi Arabia","lat":18.3,"lon":44.42,"geoPrecision":"approximate","material":"Sandstone","support":"Rock faces and large rocks","dimensions":null,"transliteration":null,"translation":null,"provenance":"Christian · Najrān region (Saudi Arabia)","synopsis":"A very important set of pre-Islamic Arabic inscriptions: Lindstedt counts twenty-three texts here, some by the same hands, with crosses engraved beside many though not all of them. The content is mostly personal names. Their importance is twofold. First, they are among the earliest Paleo-Arabic texts known from Saudi Arabia, and they show the Arabic script taking shape. Second, they show Christianity established in the far south of the peninsula in the fifth century, on the caravan road running north from Najrān, the very region the Qurʾān appears to remember when it speaks of martyrs and 'the people of the ditch'.","textCount":23,"inLindstedt":true,"additionReason":null,"references":[{"citation":"Robin, Christian Julien, ʿAlī b. Ibrāhīm al-Ghabbān, and Fāyiz al-Saʿīd. \"Inscriptions antiques de la région de Najrān (Arabie séoudite méridionale): nouveaux jalons pour l'histoire de l'écriture, de la langue et du calendrier arabes.\" Comptes rendus de l'Académie des Inscriptions et Belles-Lettres 158, no. 3 (2014): 1033–1128.","url":null},{"citation":"Nehmé, Laïla, ed. DiCoNab: Digital Corpus of the Nabataean and Developing Arabic Inscriptions, 2024–.","url":"https://diconab.huma-num.fr/"},{"citation":"Lindstedt, Ilkka. \"A Map and List of the Monotheistic Inscriptions of Arabia, 400–600 CE.\" Hadis ve Siyer Araştırmaları 10, no. 2 (2025): 275–283.","url":"https://www.hadithandsira.info/files/articles/dosya/10-2-7(1).pdf"}],"scriptFacets":["Paleo-Arabic"],"materialFacet":"Sandstone"},{"id":"hsda-1","name":"HSDA 1","siglum":"HSDA 1 (= Ḥimà-Sud PalAr 1)","religion":"christian","dateLabel":"470 CE","dateNote":"Explicitly dated: year 364 of the era of the Province of Arabia, in the month of Burak.","language":"Nabataean Aramaic and Old Arabic","script":"Paleo-Arabic","locality":"Najrān & Ḥimā","site":"Ḥimā South, c. 90 km north of Najrān","modernCountry":"Saudi Arabia","lat":18.2955,"lon":44.4285,"geoPrecision":"approximate","material":"Sandstone","support":"Movable block, deliberately placed at the foot of a mound to be visible to passers-by","dimensions":null,"transliteration":"ṯwbn [br] mlkw / byrḥ brk / s[n]t 3x100+20+20+4","translation":"Thawbān [son of] Mālik, in the month of Burak, year 364.","provenance":"Christian · Najrān region (Saudi Arabia)","synopsis":"The single most important text in the Ḥimā group, because it is precisely dated: year 364 of the era of the Roman province of Arabia, which converts to 470 CE. It is accompanied by a cross and was set on a block positioned so that travellers would see it. A firmly dated, cross-bearing Arabic inscription from 470 anchors the whole southern Paleo-Arabic corpus chronologically, and puts Christian Arabic writing in southern Arabia a full century and a half before Islam.","textCount":1,"inLindstedt":true,"additionReason":null,"references":[{"citation":"Nehmé, Laïla. \"HSDA 1.\" In DiCoNab: Digital Corpus of the Nabataean and Developing Arabic Inscriptions, edited by L. Nehmé, 2024.","url":"https://diconab.huma-num.fr/inscriptions/521"},{"citation":"Robin, Christian Julien, ʿAlī b. Ibrāhīm al-Ghabbān, and Fāyiz al-Saʿīd. \"Inscriptions antiques de la région de Najrān.\" Comptes rendus de l'Académie des Inscriptions et Belles-Lettres 158, no. 3 (2014): 1033–1128 (at 1087–1092).","url":null},{"citation":"Lindstedt, Ilkka. \"A Map and List of the Monotheistic Inscriptions of Arabia, 400–600 CE.\" Hadis ve Siyer Araştırmaları 10, no. 2 (2025): 275–283.","url":"https://www.hadithandsira.info/files/articles/dosya/10-2-7(1).pdf"}],"scriptFacets":["Paleo-Arabic"],"materialFacet":"Sandstone"},{"id":"daj144da-1","name":"DaJ144DA 1","siglum":"DaJ144DA 1 (= DaJ144PAr 1)","religion":"christian","dateLabel":"548/549 CE","dateNote":"Explicitly dated: year 443 of the era of the Province of Arabia.","language":"Old Arabic","script":"Paleo-Arabic","locality":"Dūmat al-Jandal & al-Jawf","site":"Shaʿīb al-Ẓilliyyāt (DaJ144), near Dūmat al-Jandal","modernCountry":"Saudi Arabia","lat":29.87,"lon":39.92,"geoPrecision":"approximate","material":"Sandstone","support":"Rock face or large rock","dimensions":null,"transliteration":"ḏkr / ḏkr ʾlʾlh / ḥgʿ{b/n}w br / slmh / {b}y{r}[ḥ] snt 4x100+20+20+3","translation":"May God be mindful of Ḥajjaʿ… son of Salamah, [in] the m[onth] …, year 443.","provenance":"Christian · northern Saudi Arabia (al-Jawf)","synopsis":"A dated prayer from the oasis of Dūmat al-Jandal in the far north. Three features make it valuable at once: an explicit date (548/549 CE), an invocation of God using the Arabic word al-Ilāh ('the God', the form that stands behind Allāh), and a small cross. It is thus one of the clearest cases in the whole corpus of an Arabic-speaking, Arabic-writing Christian praying to al-Ilāh in the mid-sixth century, roughly two decades before the traditional birth-date of Muhammad.","textCount":1,"inLindstedt":true,"additionReason":null,"references":[{"citation":"Nehmé, Laïla. \"DaJ144DA 1.\" In DiCoNab: Digital Corpus of the Nabataean and Developing Arabic Inscriptions, edited by L. Nehmé, 2024.","url":"https://diconab.huma-num.fr/inscriptions/520"},{"citation":"Nehmé, Laïla. \"Neue Nabatäische und Frühislamische Inschriften.\" In Archäologische Entdeckungen in Nordarabien 3 (2017): 124–132.","url":null},{"citation":"Lindstedt, Ilkka. \"A Map and List of the Monotheistic Inscriptions of Arabia, 400–600 CE.\" Hadis ve Siyer Araştırmaları 10, no. 2 (2025): 275–283.","url":"https://www.hadithandsira.info/files/articles/dosya/10-2-7(1).pdf"}],"scriptFacets":["Paleo-Arabic"],"materialFacet":"Sandstone"},{"id":"fas-5b","name":"FaS 5b","siglum":"FaS 5b (= FaS 5.2, HRahDA 5.2)","religion":"christian","dateLabel":"Undated; probably sixth century CE","dateNote":"No date in the text; assigned on palaeographic grounds.","language":"Old Arabic","script":"Paleo-Arabic","locality":"Tabūk & Ḥismā","site":"Wādī Atānah, Ḥarrat al-Rahā (between Tabūk and Hegra)","modernCountry":"Saudi Arabia","lat":27.8,"lon":37.05,"geoPrecision":"indicative","material":"Sandstone","support":"Rock face or large rock","dimensions":null,"transliteration":"ḏʾ qysw br ʾḥmr ktb lbn<y> / ʾlẖzrg slm ʾntm flʾʾwṣkm bbr ʾlʾlh / w ʾlbl w ʾlqwh","translation":"This is Qays son of Aḥmar. He wrote to Banū al-Khazraj: You are [at] peace! Indeed, he enjoins you to righteous conduct toward God, and [cultivating] close ties, and [acquiring] power.","provenance":"Christian · north-west Arabia (Saudi Arabia)","synopsis":"A moral exhortation addressed to the Banū al-Khazraj, one of the two great Arab tribes of Yathrib/Medina, the city that would later receive Muhammad. A man writes to them from the desert north of Hegra urging piety toward al-Ilāh, kinship and strength. Lindstedt argues a cross stands to the right of the second line, damaged by a later hand; if so, Qays was a Christian member of al-Khazraj. Readings of the names and of the closing words differ between editors, and the cross is not universally accepted.","textCount":1,"inLindstedt":true,"additionReason":null,"references":[{"citation":"Nehmé, Laïla, and Mohamed Hayyan. \"FaS 5.2.\" In DiCoNab: Digital Corpus of the Nabataean and Developing Arabic Inscriptions, edited by L. Nehmé, 2024.","url":"https://diconab.huma-num.fr/inscriptions/121"},{"citation":"Al-Jallad, Ahmad. \"A Paleo-Arabic Inscription on a Route North of Ṭāʾif.\" Arabian Archaeology and Epigraphy 33, no. 1 (2022): 202–215 (at 205–209).","url":"https://doi.org/10.1111/aae.12203"},{"citation":"Lindstedt, Ilkka. \"Ethical Waṣiyyas on the Eve of Islam.\" In Crossing Ancient Sacred Landscapes, edited by Michael C. A. Macdonald and Juan Manuel Tebes. Oxford: Archaeopress, forthcoming.","url":null}],"scriptFacets":["Paleo-Arabic"],"materialFacet":"Sandstone"},{"id":"hima-syriac","name":"Ḥimā Syriac inscription","siglum":"Briquel Chatonnet, Kiraz and Prioletta 2022","religion":"christian","dateLabel":"Undated; sixth or seventh century CE?","dateNote":"Undated; the editors place it broadly in the sixth or seventh century.","language":"Syriac","script":"Syriac","locality":"Najrān & Ḥimā","site":"Ḥimā area, Najrān Province","modernCountry":"Saudi Arabia","lat":18.31,"lon":44.41,"geoPrecision":"approximate","material":"Sandstone","support":"Rock face","dimensions":null,"transliteration":null,"translation":"Lord, have mercy upon me; whoever passes through this road, let him pray for me.","provenance":"Christian · Najrān region (Saudi Arabia)","synopsis":"The first Syriac inscription found in the Ḥimā area, published in 2022. Syriac was the liturgical and literary language of the Christian churches of Mesopotamia and the Persian empire, so its presence deep in southern Arabia points to real ecclesiastical connections rather than passing contact. The text is a traveller's prayer, asking those who use the same road to pray for the writer, the same road-side piety visible in the Arabic and Greek graffiti elsewhere on this map, in a third language.","textCount":1,"inLindstedt":true,"additionReason":null,"references":[{"citation":"Briquel Chatonnet, Françoise, George Kiraz, and Alessia Prioletta. \"A First Syriac Inscription from the Area of Ḥimā (Najrān Province, Southern Saudi Arabia).\" Wiener Zeitschrift für die Kunde des Morgenlandes 112 (2022): 37–49.","url":null},{"citation":"Lindstedt, Ilkka. \"A Map and List of the Monotheistic Inscriptions of Arabia, 400–600 CE.\" Hadis ve Siyer Araştırmaları 10, no. 2 (2025): 275–283.","url":"https://www.hadithandsira.info/files/articles/dosya/10-2-7(1).pdf"},{"citation":"Robin, Christian Julien. \"Ḥimyar, Aksūm, and Arabia Deserta in Late Antiquity.\" In Arabs and Empires before Islam, edited by Greg Fisher, 127–171. Oxford: Oxford University Press, 2015.","url":null}],"scriptFacets":["Syriac"],"materialFacet":"Sandstone"},{"id":"daj000da-2","name":"DaJ000DA 2","siglum":"DaJ000DA 2 (= DJTrans 1, DaJ000NabAr 1)","religion":"monotheist","dateLabel":"Undated; probably fourth–sixth century CE","dateNote":"A Roman coin of Licinius (308–324 CE) in the same collapse layer gives a terminus post quem of 308+.","language":"Old Arabic","script":"Nabataeo-Arabic","locality":"Dūmat al-Jandal & al-Jawf","site":"Rijm al-Burj, western settlement of Dūmat al-Jandal","modernCountry":"Saudi Arabia","lat":29.8117,"lon":39.8672,"geoPrecision":"exact","material":"Sandstone","support":"Stone block (found in secondary context, in a tower's collapse layer)","dimensions":null,"transliteration":"[d]kr ʾlʾlh / mlkw br {.} / ḥyh w / ṭbẖh","translation":"May God be mindful of Mālik son of Ḥayyah son of Ṭābikhah.","provenance":"Unclassified monotheist · northern Saudi Arabia (al-Jawf)","synopsis":"Excavated in 2013 at Dūmat al-Jandal, this block carries a prayer to al-Ilāh, 'the God', with no cross or other symbol to narrow the writer's affiliation further. It is now in the al-Jawf Museum (inv. O.2060-4). Because it was found in a datable archaeological layer rather than on an open rock face, it is one of the few texts in this corpus with an independent archaeological anchor for its date.","textCount":1,"inLindstedt":true,"additionReason":null,"references":[{"citation":"Nehmé, Laïla. \"DaJ000DA 2.\" In DiCoNab: Digital Corpus of the Nabataean and Developing Arabic Inscriptions, edited by L. Nehmé, 2024.","url":"https://diconab.huma-num.fr/inscriptions/519"},{"citation":"Nehmé, Laïla. \"The Religious Landscape of Northwest Arabia as Reflected in the Nabataean, Nabataeo-Arabic and Pre-Islamic Arabic Inscriptions.\" Semitica et Classica 13 (2020): 138–140.","url":null},{"citation":"Lindstedt, Ilkka. \"A Map and List of the Monotheistic Inscriptions of Arabia, 400–600 CE.\" Hadis ve Siyer Araştırmaları 10, no. 2 (2025): 275–283.","url":"https://www.hadithandsira.info/files/articles/dosya/10-2-7(1).pdf"}],"scriptFacets":["Nabataeo-Arabic"],"materialFacet":"Sandstone"},{"id":"fas-6d","name":"FaS 6d","siglum":"FaS 6d (cf. DiCoNab FaS 6.1 = HRahDA 7)","religion":"monotheist","dateLabel":"Undated; probably fifth or sixth century CE","dateNote":"No date in the text; assigned on palaeographic grounds. Note that the FaS 6 group is numbered differently by different editors.","language":"Old Arabic","script":"Paleo-Arabic","locality":"Tabūk & Ḥismā","site":"Unknown site between al-Ḥijr (Hegra) and Tabūk","modernCountry":"Saudi Arabia","lat":27.92,"lon":37.08,"geoPrecision":"indicative","material":"Sandstone","support":"Rock face or large rock","dimensions":null,"transliteration":null,"translation":null,"provenance":"Unclassified monotheist · north-west Arabia (Saudi Arabia)","synopsis":"The reading of this text is not secure, but it references God, written ʾ-l-h, as in the neighbouring inscription FaS 8. It belongs to the cluster of Paleo-Arabic graffiti published by the Saudi exploration team Farīq aṣ-Ṣaḥrāʾ from the desert between Tabūk and Hegra. Its exact findspot was not recorded, so it is placed indicatively within that corridor.","textCount":1,"inLindstedt":true,"additionReason":null,"references":[{"citation":"Farīq aṣ-Ṣaḥrāʾ. \"Arabic Inscriptions in Nabataean Style\" (in Arabic). Alsahra.org, September 2017.","url":"https://alsahra.org/?p=17938"},{"citation":"Al-Jallad, Ahmad. \"FaS 6.1.\" In DiCoNab: Digital Corpus of the Nabataean and Developing Arabic Inscriptions, edited by L. Nehmé, 2024.","url":"https://diconab.huma-num.fr/inscriptions/134"},{"citation":"Lindstedt, Ilkka. \"A Map and List of the Monotheistic Inscriptions of Arabia, 400–600 CE.\" Hadis ve Siyer Araştırmaları 10, no. 2 (2025): 275–283.","url":"https://www.hadithandsira.info/files/articles/dosya/10-2-7(1).pdf"}],"scriptFacets":["Paleo-Arabic"],"materialFacet":"Sandstone"},{"id":"fas-7","name":"FaS 7","siglum":"FaS 7 (= HRahDA 11)","religion":"monotheist","dateLabel":"Undated; probably fifth or sixth century CE","dateNote":"No date in the text; assigned on palaeographic grounds.","language":"Old Arabic","script":"Paleo-Arabic","locality":"Tabūk & Ḥismā","site":"Jabal ʿAyrayn, between Tabūk and Hegra","modernCountry":"Saudi Arabia","lat":27.88,"lon":37.02,"geoPrecision":"indicative","material":"Sandstone","support":"Rock face or large rock","dimensions":null,"transliteration":"mn ẖld br ṯʿlbh lb<n>y lẖzrg slm / ʾntm fʾḏʾ ʾtytm ʿly mkn / hḏʾ flʾwṣkm blh","translation":"From Khālid son of Thaʿlabah to Banū al-Khazraj: You are [at] peace! And when you come to this place [of mine], I enjoin you to [righteous conduct toward] God.","provenance":"Unclassified monotheist · north-west Arabia (Saudi Arabia)","synopsis":"A second letter-like text addressed to the Banū al-Khazraj of Yathrib, cut beside a rock drawing of a fighting figure. The writer imagines later travellers arriving at 'this place of mine' and reading his words, an unusually vivid sense of an audience. There is no cross and no other confessional marker, so the writer's specific affiliation is unknown; what is clear is that his piety is directed to a single God.","textCount":1,"inLindstedt":true,"additionReason":null,"references":[{"citation":"Nehmé, Laïla, and Ahmad Al-Jallad. \"FaS 7.\" In DiCoNab: Digital Corpus of the Nabataean and Developing Arabic Inscriptions, edited by L. Nehmé, 2024.","url":"https://diconab.huma-num.fr/inscriptions/86"},{"citation":"Farīq aṣ-Ṣaḥrāʾ. \"Arabic Inscriptions in Nabataean Style\" (in Arabic). Alsahra.org, 2021.","url":"https://alsahra.org/?p=17938"},{"citation":"Lindstedt, Ilkka. \"Ethical Waṣiyyas on the Eve of Islam.\" In Crossing Ancient Sacred Landscapes, edited by Michael C. A. Macdonald and Juan Manuel Tebes. Oxford: Archaeopress, forthcoming.","url":null}],"scriptFacets":["Paleo-Arabic"],"materialFacet":"Sandstone"},{"id":"fas-8","name":"FaS 8","siglum":"FaS 8 (= HRahDA 12)","religion":"monotheist","dateLabel":"Undated; probably fifth or sixth century CE","dateNote":"No date in the text; assigned on palaeographic grounds.","language":"Old Arabic","script":"Paleo-Arabic","locality":"Tabūk & Ḥismā","site":"Unknown site between al-Ḥijr (Hegra) and Tabūk","modernCountry":"Saudi Arabia","lat":27.95,"lon":37.12,"geoPrecision":"indicative","material":"Sandstone","support":"Rock face or large rock","dimensions":null,"transliteration":"ʾnʾ ṯbt br {ʾlḥ}sn / lbny ʾlẖzrg slm ʾntm / flʾʾwṣkm bbr {b/y}lh / w ʾṭʿm ʾḍyf w qtl ʾlʿdw / w ḥml ʾlʿzm w ʾlngd / w ḥykm rbkm w ʾlh ẖyr ḏʾ","translation":"I am Thābit son of al-Ḥasan; to Banū al-Khazraj, may you be at peace; so let me enjoin piety upon you toward God, and feeding the guest, and fighting the enemy, and showing determination and bravery; may your Lord give you life, for God is the best at that.","provenance":"Unclassified monotheist · north-west Arabia (Saudi Arabia)","synopsis":"The longest and richest of the Banū al-Khazraj letters. It combines an ethical code (hospitality to the guest, courage against the enemy, determination) with a closing blessing invoking 'your Lord' (rabbukum) and God. Editors have noted how closely its formulae anticipate Islamic Arabic: the greeting salm antum, the phrase bi-birri llāh ('piety toward God'), and the benediction ḥayyāka llāh. Readings of several words remain disputed.","textCount":1,"inLindstedt":true,"additionReason":null,"references":[{"citation":"Al-Jallad, Ahmad. \"FaS 8.\" In DiCoNab: Digital Corpus of the Nabataean and Developing Arabic Inscriptions, edited by L. Nehmé, 2025.","url":"https://diconab.huma-num.fr/inscriptions/137"},{"citation":"Al-Jallad, Ahmad. \"A Paleo-Arabic Inscription of a Companion of Muhammad?\" Journal of Near Eastern Studies 83, no. 1 (2024): 1–14.","url":"https://doi.org/10.1086/729531"},{"citation":"Lindstedt, Ilkka. \"Ethical Waṣiyyas on the Eve of Islam.\" In Crossing Ancient Sacred Landscapes, edited by Michael C. A. Macdonald and Juan Manuel Tebes. Oxford: Archaeopress, forthcoming.","url":null}],"scriptFacets":["Paleo-Arabic"],"materialFacet":"Sandstone"},{"id":"fas-9","name":"FaS 9","siglum":"FaS 9","religion":"monotheist","dateLabel":"Undated; probably fifth or sixth century CE","dateNote":"No date in the text; assigned on palaeographic grounds.","language":"Old Arabic","script":"Paleo-Arabic","locality":"Tabūk & Ḥismā","site":"Unknown site between al-Ḥijr (Hegra) and Tabūk","modernCountry":"Saudi Arabia","lat":27.9,"lon":37.15,"geoPrecision":"indicative","material":"Sandstone","support":"Rock face or large rock","dimensions":null,"transliteration":"bsm ʾllh …","translation":"In the name of God … (remainder awaiting detailed study).","provenance":"Unclassified monotheist · north-west Arabia (Saudi Arabia)","synopsis":"The text opens with bism Allāh, 'in the name of God', the formula that would become the Islamic basmala. The rest of the inscription has not yet been read in detail. Pre-Islamic occurrences of this phrase (see also the Jabal Dhabūb inscription in Yemen) matter because they show the formula was already in use as an Arabian invocation before the Qurʾān adopted and standardised it.","textCount":1,"inLindstedt":true,"additionReason":null,"references":[{"citation":"Farīq aṣ-Ṣaḥrāʾ. \"Arabic Inscriptions in Nabataean Style\" (in Arabic). Alsahra.org, September 2017.","url":"https://alsahra.org/?p=17938"},{"citation":"Al-Jallad, Ahmad. \"The Pre-Islamic Basmala: Reflections on Its First Epigraphic Attestation and Its Original Significance.\" Journal of the International Qurʾanic Studies Association (2022).","url":"https://almuslih.org/wp-content/uploads/Library/Jallad,%20A%20-%20The%20pre-Islamic%20Basmala.pdf"},{"citation":"Lindstedt, Ilkka. \"A Map and List of the Monotheistic Inscriptions of Arabia, 400–600 CE.\" Hadis ve Siyer Araştırmaları 10, no. 2 (2025): 275–283.","url":"https://www.hadithandsira.info/files/articles/dosya/10-2-7(1).pdf"}],"scriptFacets":["Paleo-Arabic"],"materialFacet":"Sandstone"},{"id":"arda-1","name":"ArDA 1","siglum":"ArDA 1","religion":"monotheist","dateLabel":"505/506 CE","dateNote":"Dated to year 400 of the era of the Province of Arabia; the reading of the numeral is not completely certain, but the palaeography matches other sixth-century texts.","language":"Old Arabic","script":"Paleo-Arabic","locality":"Tabūk & Ḥismā","site":"Al-ʿArniyyāt, on the Darb al-Bakrah caravan route","modernCountry":"Saudi Arabia","lat":27.35,"lon":37.55,"geoPrecision":"indicative","material":"Sandstone","support":"Rock face or large rock","dimensions":null,"transliteration":"smʿ / ḏkr ʾlʾlh / ṭrdw br slmn / w mn dʿʾ bsmh / 3x100+100 [----]","translation":"May He listen! May God be mindful of Ṭarrād son of Salmān, and of whoever invokes His name, [in the year] 400.","provenance":"Unclassified monotheist · north-west Arabia (Saudi Arabia)","synopsis":"A dated prayer with a striking extension: the writer asks God to remember not only himself but 'whoever invokes His name', the first attestation of this formula, opening the blessing to every future reader. It was rediscovered by Laïla Nehmé in 2024 while reviewing photographs that had been filed as 'Islamic'. The editors note that, unlike other sixth-century al-Ilāh texts, this one carries no cross, so a Christian identification is not certain.","textCount":1,"inLindstedt":true,"additionReason":null,"references":[{"citation":"Nehmé, Laïla. \"ArDA 1.\" In DiCoNab: Digital Corpus of the Nabataean and Developing Arabic Inscriptions, edited by L. Nehmé, 2024.","url":"https://diconab.huma-num.fr/inscriptions/518"},{"citation":"Nehmé, Laïla. \"Bulletin épigraphique.\" Syria 101 (2024): 309–310.","url":null},{"citation":"Lindstedt, Ilkka. \"A Map and List of the Monotheistic Inscriptions of Arabia, 400–600 CE.\" Hadis ve Siyer Araştırmaları 10, no. 2 (2025): 275–283.","url":"https://www.hadithandsira.info/files/articles/dosya/10-2-7(1).pdf"}],"scriptFacets":["Paleo-Arabic"],"materialFacet":"Sandstone"},{"id":"daj000da-3","name":"DaJ000DA 3","siglum":"DaJ000DA 3","religion":"monotheist","dateLabel":"548/549 CE","dateNote":"Explicitly dated: year 443 of the era of the Province of Arabia.","language":"Old Arabic","script":"Paleo-Arabic","locality":"Dūmat al-Jandal & al-Jawf","site":"Jabal Ḥalmah, near Dūmat al-Jandal","modernCountry":"Saudi Arabia","lat":29.7,"lon":39.65,"geoPrecision":"indicative","material":"Sandstone","support":"Rock face or large rock","dimensions":null,"transliteration":"ḏkr ʾlʾlh gnd / dwmh {ġ}wʾ / {ʿ}wʾ s{nt} / 4x100+20+20+3 fʾgbwʾ ʾmrh","translation":"May God be mindful of the troop from Dūmah who perished, year 443, having responded to His command. (Alternatively: '…the troop from Dūmah. He called them to conflict, year 443, and they responded to his command.')","provenance":"Unclassified monotheist · northern Saudi Arabia (al-Jawf)","synopsis":"A dated memorial for a military unit from Dūmah, the only text in Lindstedt's list that commemorates a group of war dead rather than an individual. The grammar is genuinely difficult and the editors, Ahmad Al-Jallad and Laïla Nehmé, offer two readings: either the troop perished, or God summoned them to battle and they obeyed. Either way it shows an Arabic-writing community in 548/549 framing collective death in the language of obedience to one God.","textCount":1,"inLindstedt":true,"additionReason":null,"references":[{"citation":"Nehmé, Laïla. \"DaJ000DA 3.\" In DiCoNab: Digital Corpus of the Nabataean and Developing Arabic Inscriptions, edited by L. Nehmé, 2024.","url":"https://diconab.huma-num.fr/inscriptions/130"},{"citation":"Nehmé, Laïla. \"Bulletin épigraphique.\" Syria 101 (2024): 310–311.","url":null},{"citation":"Lindstedt, Ilkka. \"A Map and List of the Monotheistic Inscriptions of Arabia, 400–600 CE.\" Hadis ve Siyer Araştırmaları 10, no. 2 (2025): 275–283.","url":"https://www.hadithandsira.info/files/articles/dosya/10-2-7(1).pdf"}],"scriptFacets":["Paleo-Arabic"],"materialFacet":"Sandstone"},{"id":"nraa-4","name":"NRAA 4 (Umm Burayrah inscription)","siglum":"NRAA 4","religion":"monotheist","dateLabel":"Undated; probably sixth century CE","dateNote":"No date in the text; assigned on palaeographic grounds.","language":"Old Arabic","script":"Paleo-Arabic","locality":"Tabūk & Ḥismā","site":"Umm Burayrah, Ḥismā desert (Tabūk region), north-west Ḥijāz","modernCountry":"Saudi Arabia","lat":28.7,"lon":36.2,"geoPrecision":"indicative","material":"Sandstone","support":"Rock face or large rock","dimensions":null,"transliteration":"bsmk ʾllhm ʾnʾ ʿbdšms br ʾlmġyrh ystġfr rbh","translation":"In your name, O God! I am ʿAbd Shams son of al-Mughīra, who seeks the forgiveness of his Lord.","provenance":"Unclassified monotheist · north-west Arabia (Saudi Arabia)","synopsis":"A prayer opening with bi-smika allāhumma, 'In your name, O God', the invocation that Muslim tradition remembers as the pre-Islamic Arabian formula which the basmala replaced. The writer uses the word Rabb, 'Lord', and asks forgiveness. The name ʿAbd Shams ('servant of the Sun') is a theophoric name from the older polytheistic naming stock, worn here by a man praying to a single God: a neat illustration that names are weak evidence of belief.","textCount":1,"inLindstedt":true,"additionReason":null,"references":[{"citation":"Nehmé, Laïla. \"NRAA 4.\" In DiCoNab: Digital Corpus of the Nabataean and Developing Arabic Inscriptions, edited by L. Nehmé, 2024.","url":"https://diconab.huma-num.fr/inscriptions/157"},{"citation":"Alhatlani, Abdullah Saad, and Ajab Mohammad Al-Otibi. \"A Palaeo-Arabic Inscription from the Ḥismā Desert (Tabūk Region).\" Arabian Archaeology and Epigraphy 34, no. 1 (2023): 183–193.","url":"https://doi.org/10.1111/aae.12235"},{"citation":"Al-Jallad, Ahmad. \"A Paleo-Arabic Inscription on a Route North of Ṭāʾif.\" Arabian Archaeology and Epigraphy 33, no. 1 (2022): 202–215 (at 210).","url":"https://doi.org/10.1111/aae.12203"}],"scriptFacets":["Paleo-Arabic"],"materialFacet":"Sandstone"},{"id":"fas-4","name":"FaS 4","siglum":"FaS 4 (= HRahDA 04)","religion":"monotheist","dateLabel":"Undated; probably sixth century CE","dateNote":"No date in the text; assigned on palaeographic grounds.","language":"Old Arabic","script":"Paleo-Arabic","locality":"Tabūk & Ḥismā","site":"Unknown site between al-Ḥijr (Hegra) and Tabūk","modernCountry":"Saudi Arabia","lat":27.86,"lon":37.18,"geoPrecision":"indicative","material":"Sandstone","support":"Rock face or large rock","dimensions":null,"transliteration":"ʿdyw br ʾl{d/ḏ}ʾ{b/n}h / lbny ʿwṣ slm ʾntm / flʾʾwṣkm bbr {b/y}lh / w lqwh w lrmḥ w lẖyl / w qtl ʾlqwm w tqʾ ʾlrḥm w krmt ʾlḍyf","translation":"ʿAdī son of al-Dhiʾbah to the Banū ʿAwṣ: You are [at] peace! So let me enjoin you to piety toward God, and might, and the spear, and the horse, and warfare against the enemy, and preserving the bonds of kinship, and honouring the guest.","provenance":"Unclassified monotheist · north-west Arabia (Saudi Arabia)","synopsis":"A third exhortation in the same north-west Arabian genre, this one addressed to the Banū ʿAwṣ. The list of virtues fuses two worlds: piety toward God on one side, and the classic warrior-and-host ethic of Arabian tribal poetry (the spear, the horse, kinship, hospitality) on the other. Texts like this are why scholars increasingly describe pre-Islamic Arabian monotheism as fully at home in tribal society rather than a foreign import layered on top of it.","textCount":1,"inLindstedt":true,"additionReason":null,"references":[{"citation":"Nehmé, Laïla. \"FaS 4.\" In DiCoNab: Digital Corpus of the Nabataean and Developing Arabic Inscriptions, edited by L. Nehmé, 2024.","url":"https://diconab.huma-num.fr/inscriptions/125"},{"citation":"Al-Jallad, Ahmad. \"A Paleo-Arabic Inscription of a Companion of Muhammad?\" Journal of Near Eastern Studies 83, no. 1 (2024): 1–14 (at 9).","url":"https://doi.org/10.1086/729531"},{"citation":"Lindstedt, Ilkka. \"Ethical Waṣiyyas on the Eve of Islam.\" In Crossing Ancient Sacred Landscapes, edited by Michael C. A. Macdonald and Juan Manuel Tebes. Oxford: Archaeopress, forthcoming.","url":null}],"scriptFacets":["Paleo-Arabic"],"materialFacet":"Sandstone"},{"id":"wadi-al-naqib-5","name":"Wādī al-Naqīb 5","siglum":"Wādī al-Naqīb 5","religion":"monotheist","dateLabel":"Undated; probably sixth century CE","dateNote":"No date in the text; assigned on palaeographic grounds and by its close parallel with NRAA 4.","language":"Old Arabic","script":"Paleo-Arabic","locality":"Tabūk & Ḥismā","site":"Wādī al-Naqīb, between Tabūk and al-ʿUlā","modernCountry":"Saudi Arabia","lat":27.6,"lon":37.3,"geoPrecision":"indicative","material":"Sandstone","support":"Rock face or large rock","dimensions":null,"transliteration":"bsmk ʾllhm … br ʿwf …","translation":"In your name, O God! … son of ʿAwf … (parts of the reading remain uncertain).","provenance":"Unclassified monotheist · north-west Arabia (Saudi Arabia)","synopsis":"Published on the Farīq aṣ-Ṣaḥrāʾ website in 2024, this text opens with exactly the same invocation as NRAA 4, bi-smika allāhumma, and mentions Allāh. The repetition of an identical opening formula at two separate sites in north-west Arabia suggests a shared devotional convention rather than individual improvisation: there was a normal way to begin a prayer in sixth-century Arabic, and this was it.","textCount":1,"inLindstedt":true,"additionReason":null,"references":[{"citation":"Farīq aṣ-Ṣaḥrāʾ. \"Winter Journey 1445 AH, 5: Lower Wādī al-Naqīb\" (in Arabic). Alsahra.org, July 2024.","url":"https://alsahra.org/2024/07/"},{"citation":"Lindstedt, Ilkka. \"A Map and List of the Monotheistic Inscriptions of Arabia, 400–600 CE.\" Hadis ve Siyer Araştırmaları 10, no. 2 (2025): 275–283.","url":"https://www.hadithandsira.info/files/articles/dosya/10-2-7(1).pdf"},{"citation":"Alhatlani, Abdullah Saad, and Ajab Mohammad Al-Otibi. \"A Palaeo-Arabic Inscription from the Ḥismā Desert (Tabūk Region).\" Arabian Archaeology and Epigraphy 34, no. 1 (2023): 183–193.","url":"https://doi.org/10.1111/aae.12235"}],"scriptFacets":["Paleo-Arabic"],"materialFacet":"Sandstone"},{"id":"z-2","name":"Z 2 (Rīʿ al-Zallālah inscription)","siglum":"Z 2","religion":"monotheist","dateLabel":"Undated; possibly sixth century CE","dateNote":"No date in the text; assigned on palaeographic grounds by Al-Jallad and Sidky.","language":"Old Arabic","script":"Paleo-Arabic","locality":"Ḥijāz & Ṭāʾif","site":"Rīʿ al-Zallālah, a pass north of Ṭāʾif on the route toward al-Sayl al-Kabīr","modernCountry":"Saudi Arabia","lat":21.45,"lon":40.36,"geoPrecision":"approximate","material":"Granite","support":"Rock face in a mountain pass","dimensions":null,"transliteration":"brk[k]m rbnʾ / ʾnʾ qrh / br sd","translation":"May our Lord bless you. I am Qurra son of Sadd.","provenance":"Unclassified monotheist · Ḥijāz (Saudi Arabia)","synopsis":"Cut into a pass on the road between Mecca and Ṭāʾif, this is the closest monotheistic inscription to Mecca yet published. Al-Jallad and Sidky suggest the writer was a traveller on that route. The blessing formula 'may our Lord bless you' uses vocabulary with Hebrew and Aramaic resonance, and the text preserves an early example of a vowel-assimilation feature later described by Classical Arabic grammarians. Its importance is its location: monotheist devotion at the doorstep of pre-Islamic Mecca.","textCount":1,"inLindstedt":true,"additionReason":null,"references":[{"citation":"Al-Jallad, Ahmad, and Hythem Sidky. \"A Paleo-Arabic Inscription on a Route North of Ṭāʾif.\" Arabian Archaeology and Epigraphy 33, no. 1 (2022): 202–215.","url":"https://doi.org/10.1111/aae.12203"},{"citation":"Lindstedt, Ilkka. \"A Map and List of the Monotheistic Inscriptions of Arabia, 400–600 CE.\" Hadis ve Siyer Araştırmaları 10, no. 2 (2025): 275–283.","url":"https://www.hadithandsira.info/files/articles/dosya/10-2-7(1).pdf"},{"citation":"Lindstedt, Ilkka. Muḥammad and His Followers in Context: The Religious Map of Late Antique Arabia. Leiden: Brill, 2024.","url":"https://doi.org/10.1163/9789004687134"}],"scriptFacets":["Paleo-Arabic"],"materialFacet":"Granite"},{"id":"aljallad-sidky-2024-1","name":"Al-Jallad and Sidky 2024, no. 1 (the Ḥanẓala inscription)","siglum":"Al-Jallad & Sidky 2024, no. 1","religion":"monotheist","dateLabel":"Undated; probably late sixth or early seventh century CE","dateNote":"No date in the text; the editors place it in the lifetime of Muhammad on palaeographic and onomastic grounds.","language":"Old Arabic","script":"Paleo-Arabic","locality":"Ḥijāz & Ṭāʾif","site":"Near Ṭāʾif","modernCountry":"Saudi Arabia","lat":21.36,"lon":40.31,"geoPrecision":"approximate","material":"Granite","support":"Boulder (shared with no. 2)","dimensions":null,"transliteration":"bsmk rbnʾ ʾnʾ ḥnẓlh bn ʿbd ʿmrw ʾwṣy bbr ʾllh","translation":"In your name, our Lord! I am Ḥanẓala son of ʿAbd ʿAmr; I enjoin righteousness toward God.","provenance":"Unclassified monotheist · Ḥijāz (Saudi Arabia)","synopsis":"One of the most discussed finds of recent years. Al-Jallad and Sidky raise the possibility that this Ḥanẓala son of ʿAbd ʿAmr is the man Muslim tradition knows as Ḥanẓala ibn Abī ʿĀmir, a Companion of Muhammad, in which case the inscription would record his monotheist piety before the coming of Islam. The identification is proposed as a question, not a conclusion. Either way, the text shows a man near Ṭāʾif around 600 CE using the vocabulary of monotheist devotion.","textCount":1,"inLindstedt":true,"additionReason":null,"references":[{"citation":"Al-Jallad, Ahmad, and Hythem Sidky. \"A Paleo-Arabic Inscription of a Companion of Muhammad?\" Journal of Near Eastern Studies 83, no. 1 (2024): 1–14.","url":"https://doi.org/10.1086/729531"},{"citation":"Lindstedt, Ilkka. \"A Map and List of the Monotheistic Inscriptions of Arabia, 400–600 CE.\" Hadis ve Siyer Araştırmaları 10, no. 2 (2025): 275–283.","url":"https://www.hadithandsira.info/files/articles/dosya/10-2-7(1).pdf"},{"citation":"Lindstedt, Ilkka. Muḥammad and His Followers in Context: The Religious Map of Late Antique Arabia. Leiden: Brill, 2024.","url":"https://doi.org/10.1163/9789004687134"}],"scriptFacets":["Paleo-Arabic"],"materialFacet":"Granite"},{"id":"aljallad-sidky-2024-2","name":"Al-Jallad and Sidky 2024, no. 2 (the ʿAbd al-ʿUzzā inscription)","siglum":"Al-Jallad & Sidky 2024, no. 2","religion":"monotheist","dateLabel":"Undated; probably late sixth or early seventh century CE","dateNote":"No date in the text; contemporary with no. 1, on the same rock.","language":"Old Arabic","script":"Paleo-Arabic","locality":"Ḥijāz & Ṭāʾif","site":"Near Ṭāʾif (same rock as no. 1)","modernCountry":"Saudi Arabia","lat":21.363,"lon":40.315,"geoPrecision":"approximate","material":"Granite","support":"Boulder (shared with no. 1)","dimensions":null,"transliteration":null,"translation":"Written by ʿAbd al-ʿUzzā son of Sufyān, with monotheistic content mentioning Allāh.","provenance":"Unclassified monotheist · Ḥijāz (Saudi Arabia)","synopsis":"The most theologically interesting text on this map. The writer's name means 'servant of al-ʿUzzā', one of the three goddesses named in the Qurʾān, yet his inscription is monotheistic and invokes Allāh. Lindstedt suggests this may be evidence of henotheism: acknowledging Allāh as Creator and High God while still recognising other deities. It is a caution against reading the epigraphic record as proof that polytheism had simply vanished, and a reminder that late antique Arabian belief was a spectrum rather than a set of sealed boxes.","textCount":1,"inLindstedt":true,"additionReason":null,"references":[{"citation":"Al-Jallad, Ahmad, and Hythem Sidky. \"A Paleo-Arabic Inscription of a Companion of Muhammad?\" Journal of Near Eastern Studies 83, no. 1 (2024): 1–14.","url":"https://doi.org/10.1086/729531"},{"citation":"Lindstedt, Ilkka. \"A Map and List of the Monotheistic Inscriptions of Arabia, 400–600 CE.\" Hadis ve Siyer Araştırmaları 10, no. 2 (2025): 275–283.","url":"https://www.hadithandsira.info/files/articles/dosya/10-2-7(1).pdf"},{"citation":"Sinai, Nicolai. Rain-Giver, Bone-Breaker, Score-Settler: Allāh in Pre-Quranic Poetry. New Haven: American Oriental Society, 2019.","url":"https://doi.org/10.5913/2019488259"}],"scriptFacets":["Paleo-Arabic"],"materialFacet":"Granite"},{"id":"ja-1028","name":"Ja 1028","siglum":"Ja 1028","religion":"jewish","dateLabel":"523 CE","dateNote":"Dated to the month Dhū-Madhraʾān of the year 633 of the Ḥimyarite era.","language":"Sabaic","script":"Ancient South Arabian (Musnad)","locality":"Najrān & Ḥimā","site":"Biʾr Ḥimā, c. 85 km north-east of Najrān","modernCountry":"Saudi Arabia","lat":18.325,"lon":44.45,"geoPrecision":"approximate","material":"Rock","support":"Rock face","dimensions":null,"transliteration":null,"translation":null,"provenance":"Jewish · Ḥimyarite kingdom (found in modern Saudi Arabia)","synopsis":"A campaign inscription of Sharaḥʾīl Yaqbul, a commander of the Jewish Ḥimyarite king Yūsuf As'ar Yathʾar (Dhū Nuwās). It records the burning of the church at Najrān and the killing of Abyssinians at Ẓafār, and invokes Raḥmānān, 'the Merciful', together with the Lord of the Jews. This is the epigraphic face of the Najrān massacre of 523, an event that echoed across the Christian world, drew an Aksūmite invasion, and is widely thought to lie behind the Qurʾānic passage on the 'people of the ditch' (Q 85).","textCount":1,"inLindstedt":false,"additionReason":"Ancient South Arabian material, explicitly excluded from Lindstedt's list; included here to represent the ~200-item Late Sabaic monotheistic corpus he points to.","references":[{"citation":"Robin, Christian Julien. \"Ḥimyar, Aksūm, and Arabia Deserta in Late Antiquity.\" In Arabs and Empires before Islam, edited by Greg Fisher, 127–171. Oxford: Oxford University Press, 2015.","url":null},{"citation":"Gajda, Iwona. Le royaume de Ḥimyar à l'époque monothéiste. Paris: De Boccard, 2009.","url":null},{"citation":"Avanzini, Alessandra, ed. Corpus of South Arabian Inscriptions (DASI).","url":"https://dasi.cnr.it/"}],"scriptFacets":["Ancient South Arabian"],"materialFacet":"Rock (unspecified)"},{"id":"ry-507","name":"Ry 507","siglum":"Ry 507","religion":"jewish","dateLabel":"523 CE","dateNote":"Dated to the year 633 of the Ḥimyarite era.","language":"Sabaic","script":"Ancient South Arabian (Musnad)","locality":"Najrān & Ḥimā","site":"Biʾr Ḥimā, north of Najrān","modernCountry":"Saudi Arabia","lat":18.34,"lon":44.44,"geoPrecision":"approximate","material":"Rock","support":"Rock face","dimensions":null,"transliteration":null,"translation":null,"provenance":"Jewish · Ḥimyarite kingdom (found in modern Saudi Arabia)","synopsis":"One of three inscriptions documenting the Ḥimyarite campaign against the Christians of Najrān, carved at the rock-art site of Biʾr Ḥimā where the army encamped. Like its companions it invokes Raḥmānān and reflects the Jewish orientation of the Ḥimyarite monarchy in its final decades. Its presence at the same site as the Christian Paleo-Arabic graffiti of Ḥimā makes this one location a compressed record of the confessional conflict of sixth-century Arabia.","textCount":1,"inLindstedt":false,"additionReason":"Ancient South Arabian material, excluded from Lindstedt's list by scope.","references":[{"citation":"Robin, Christian Julien. \"Ḥimyar, Aksūm, and Arabia Deserta in Late Antiquity.\" In Arabs and Empires before Islam, edited by Greg Fisher, 127–171. Oxford: Oxford University Press, 2015.","url":null},{"citation":"Gajda, Iwona. Le royaume de Ḥimyar à l'époque monothéiste. Paris: De Boccard, 2009.","url":null},{"citation":"Avanzini, Alessandra, ed. Corpus of South Arabian Inscriptions (DASI).","url":"https://dasi.cnr.it/"}],"scriptFacets":["Ancient South Arabian"],"materialFacet":"Rock (unspecified)"},{"id":"ry-508","name":"Ry 508","siglum":"Ry 508","religion":"jewish","dateLabel":"523 CE","dateNote":"Dated to the year 633 of the Ḥimyarite era.","language":"Sabaic","script":"Ancient South Arabian (Musnad)","locality":"Najrān & Ḥimā","site":"Kawkab, near Ḥimā, north of Najrān","modernCountry":"Saudi Arabia","lat":18.22,"lon":44.32,"geoPrecision":"indicative","material":"Rock","support":"Rock face","dimensions":null,"transliteration":null,"translation":null,"provenance":"Jewish · Ḥimyarite kingdom (found in modern Saudi Arabia)","synopsis":"The third of the Ḥimyarite campaign texts of 523, carved a short distance from Ry 507. Together the three inscriptions let historians reconstruct the movements of Yūsuf's army in the year of the Najrān persecution, a rare case where Arabian epigraphy provides a datable military narrative that can be set beside Syriac and Greek accounts of the same events written far outside Arabia.","textCount":1,"inLindstedt":false,"additionReason":"Ancient South Arabian material, excluded from Lindstedt's list by scope.","references":[{"citation":"Robin, Christian Julien. \"Ḥimyar, Aksūm, and Arabia Deserta in Late Antiquity.\" In Arabs and Empires before Islam, edited by Greg Fisher, 127–171. Oxford: Oxford University Press, 2015.","url":null},{"citation":"Gajda, Iwona. Le royaume de Ḥimyar à l'époque monothéiste. Paris: De Boccard, 2009.","url":null},{"citation":"Avanzini, Alessandra, ed. Corpus of South Arabian Inscriptions (DASI).","url":"https://dasi.cnr.it/"}],"scriptFacets":["Ancient South Arabian"],"materialFacet":"Rock (unspecified)"},{"id":"garb-bayt-al-ashwal-1","name":"Garb Bayt al-Ashwal 1","siglum":"Garb Bayt al-Ashwal 1","religion":"jewish","dateLabel":"Undated; c. 380–420 CE","dateNote":"Undated; placed in the decades around 400 CE on the basis of script and historical context.","language":"Sabaic, with a Hebrew graffito","script":"Ancient South Arabian (Musnad), with Hebrew","locality":"South Arabia (Ḥimyar)","site":"Ẓafār, capital of the Ḥimyarite kingdom","modernCountry":"Yemen","lat":14.21,"lon":44.4,"geoPrecision":"approximate","material":"Limestone","support":"Building inscription","dimensions":null,"transliteration":null,"translation":"…with the assistance and grace of his Lord, who created his soul, the Lord of the living and the dead, the Lord of the sky and the earth, who created all… (with the Hebrew words 'amen, shalom' added).","provenance":"Jewish · Ḥimyarite kingdom (Yemen)","synopsis":"A building inscription of one Yehūdā Yakkuf at the Ḥimyarite capital. The Sabaic text praises a single creator God in the abstract, universalising language typical of Ḥimyarite monotheism; a small Hebrew graffito reading 'amen, shalom' incised in the monogram settles the author's Jewish identity. It is a key document for the argument that the Ḥimyarite kings and elite converted to a form of Judaism around 380 CE and abandoned the old South Arabian pantheon.","textCount":1,"inLindstedt":false,"additionReason":"Ancient South Arabian material, excluded from Lindstedt's list by scope.","references":[{"citation":"Robin, Christian Julien. \"The Judaism of the Ancient Kingdom of Ḥimyar in Arabia: A Discreet Conversion.\" In Diversity and Rabbinization, edited by Gavin McDowell et al. Cambridge: Open Book Publishers, 2021.","url":"https://books.openedition.org/obp/19970?lang=en"},{"citation":"Gajda, Iwona. Le royaume de Ḥimyar à l'époque monothéiste. Paris: De Boccard, 2009.","url":null},{"citation":"Avanzini, Alessandra, ed. Corpus of South Arabian Inscriptions (DASI).","url":"https://dasi.cnr.it/"}],"scriptFacets":["Ancient South Arabian","Hebrew"],"materialFacet":"Limestone"},{"id":"dje-23","name":"DJE 23 (the priestly courses inscription)","siglum":"DJE 23","religion":"jewish","dateLabel":"Undated; fourth–sixth century CE","dateNote":"Undated; assigned to the Ḥimyarite monotheistic period.","language":"Hebrew","script":"Hebrew","locality":"South Arabia (Ḥimyar)","site":"Bayt Ḥāḍir, east of Ṣanʿāʾ","modernCountry":"Yemen","lat":15.28,"lon":44.35,"geoPrecision":"approximate","material":"Stone","support":"Carved stone slab","dimensions":null,"transliteration":null,"translation":null,"provenance":"Jewish · Ḥimyarite kingdom (Yemen)","synopsis":"A list of the twenty-four priestly courses (mishmarot), the rotating families who had served in the Jerusalem Temple, paired with their Galilean home villages. Yemen is the only place outside Palestine where such a list has been found carved in stone. Commissioning it was expensive and pointedly symbolic: a South Arabian Jewish community declaring its attachment to the Temple and to hopes for its restoration, from fifteen hundred kilometres away.","textCount":1,"inLindstedt":false,"additionReason":"Hebrew-script material from South Arabia, outside the scope of Lindstedt's list.","references":[{"citation":"Robin, Christian Julien. \"The Judaism of the Ancient Kingdom of Ḥimyar in Arabia: A Discreet Conversion.\" In Diversity and Rabbinization, edited by Gavin McDowell et al. Cambridge: Open Book Publishers, 2021.","url":"https://books.openedition.org/obp/19970?lang=en"},{"citation":"Gajda, Iwona. Le royaume de Ḥimyar à l'époque monothéiste. Paris: De Boccard, 2009.","url":null},{"citation":"Lindstedt, Ilkka. Muḥammad and His Followers in Context: The Religious Map of Late Antique Arabia. Leiden: Brill, 2024.","url":"https://doi.org/10.1163/9789004687134"}],"scriptFacets":["Hebrew"],"materialFacet":"Stone"},{"id":"mafray-hasi-1","name":"MAFRAY-Ḥaṣī 1","siglum":"MAFRAY-Ḥaṣī 1","religion":"jewish","dateLabel":"Fifth century CE","dateNote":"Dated by the Ḥimyarite era in the text; the reading places it in the later fifth century.","language":"Sabaic","script":"Ancient South Arabian (Musnad)","locality":"South Arabia (Ḥimyar)","site":"Ḥaṣī, c. 220 km south-east of Ṣanʿāʾ","modernCountry":"Yemen","lat":14.5,"lon":45.6,"geoPrecision":"indicative","material":"Stone","support":"Inscribed slab","dimensions":null,"transliteration":null,"translation":null,"provenance":"Jewish · Ḥimyarite kingdom (Yemen)","synopsis":"A legal text converting four plots of land into a cemetery reserved for Jews, and adding a plot and a well to the endowment of the mikrāb (synagogue) of Ṣūrīʾel. It is one of the most concrete documents of institutional Judaism in South Arabia: a synagogue with a named custodian (ḥazzān), landed endowments, and a community with the authority to declare a burial ground exclusive. This is organised communal religion, not scattered individual belief.","textCount":1,"inLindstedt":false,"additionReason":"Ancient South Arabian material, excluded from Lindstedt's list by scope.","references":[{"citation":"Robin, Christian Julien. \"The Judaism of the Ancient Kingdom of Ḥimyar in Arabia: A Discreet Conversion.\" In Diversity and Rabbinization, edited by Gavin McDowell et al. Cambridge: Open Book Publishers, 2021.","url":"https://books.openedition.org/obp/19970?lang=en"},{"citation":"Gajda, Iwona. Le royaume de Ḥimyar à l'époque monothéiste. Paris: De Boccard, 2009.","url":null},{"citation":"Avanzini, Alessandra, ed. Corpus of South Arabian Inscriptions (DASI).","url":"https://dasi.cnr.it/"}],"scriptFacets":["Ancient South Arabian"],"materialFacet":"Stone"},{"id":"cih-541","name":"CIH 541 (the Mārib dam inscription of Abraha)","siglum":"CIH 541","religion":"christian","dateLabel":"548 CE","dateNote":"Dated by the Ḥimyarite era; commemorates repairs to the Mārib dam.","language":"Sabaic","script":"Ancient South Arabian (Musnad)","locality":"South Arabia (Ḥimyar)","site":"Mārib, at the great dam","modernCountry":"Yemen","lat":15.4,"lon":45.35,"geoPrecision":"approximate","material":"Stone","support":"Monumental inscribed stone; 136 lines","dimensions":"136 lines, the longest known inscription of Abraha","transliteration":null,"translation":null,"provenance":"Christian · Ḥimyarite kingdom (Yemen)","synopsis":"The longest surviving inscription of Abraha, the Christian king of Ḥimyar. It opens with a Trinitarian thanksgiving invoking Raḥmānān, his Messiah and the Holy Spirit, then turns to the repair of the Mārib dam, the celebration of a mass in the church at Mārib, and the reception of embassies from Aksūm, Byzantium, Persia and the Arab kingdoms. It is the single clearest statement that a formally Christian state governed South Arabia in the mid-sixth century, and Abraha is the king Muslim tradition remembers in the sūra of the Elephant (Q 105).","textCount":1,"inLindstedt":false,"additionReason":"Ancient South Arabian material, excluded from Lindstedt's list by scope, though he cites Abraha's Ry 506 as an example of it.","references":[{"citation":"Robin, Christian Julien. \"Ḥimyar, Aksūm, and Arabia Deserta in Late Antiquity.\" In Arabs and Empires before Islam, edited by Greg Fisher, 127–171. Oxford: Oxford University Press, 2015.","url":null},{"citation":"Gajda, Iwona. Le royaume de Ḥimyar à l'époque monothéiste. Paris: De Boccard, 2009.","url":null},{"citation":"Avanzini, Alessandra, ed. Corpus of South Arabian Inscriptions (DASI).","url":"https://dasi.cnr.it/"}],"scriptFacets":["Ancient South Arabian"],"materialFacet":"Stone"},{"id":"ry-506","name":"Ry 506 (Murayghān 1)","siglum":"Ry 506 = Murayghān 1","religion":"christian","dateLabel":"552 CE","dateNote":"Dated to Dhū-ʾĀlān of the year 662 of the Ḥimyarite era (December 552).","language":"Sabaic","script":"Ancient South Arabian (Musnad)","locality":"South Arabia (Ḥimyar)","site":"Biʾr Murayghān, in the Tathlīth area of southern Saudi Arabia","modernCountry":"Saudi Arabia","lat":19.0535,"lon":43.7803,"geoPrecision":"exact","material":"Rock","support":"Rock face","dimensions":null,"transliteration":null,"translation":null,"provenance":"Christian · commissioned by Abraha of Ḥimyar (found in modern Saudi Arabia)","synopsis":"Abraha's account of his fourth campaign against the tribal confederation of Maʿadd in central Arabia, cut into rock far north of his capital. Lindstedt cites it as an example of the Christian Sabaic material found inside modern Saudi Arabia, and gives its coordinates precisely. Christian Robin's re-reading transformed our picture of the campaign, showing a successful expedition that installed a friendly governor, evidence that Christian Ḥimyarite power reached deep into the Arabian interior a generation before Muhammad.","textCount":1,"inLindstedt":true,"additionReason":null,"references":[{"citation":"Robin, Christian Julien. \"Abraha et la reconquête de l'Arabie déserte: un réexamen de l'inscription Ryckmans 506 = Murayghān 1.\" Jerusalem Studies in Arabic and Islam 39 (2012): 1–93.","url":null},{"citation":"Avanzini, Alessandra, ed. \"Ry 506 Murayghān 1.\" Corpus of South Arabian Inscriptions (DASI).","url":"https://dasi.cnr.it/index.php?id=79&prjId=1&corId=7&colId=0&navId=699644996&recId=2447"},{"citation":"Lindstedt, Ilkka. \"A Map and List of the Monotheistic Inscriptions of Arabia, 400–600 CE.\" Hadis ve Siyer Araştırmaları 10, no. 2 (2025): 275–283.","url":"https://www.hadithandsira.info/files/articles/dosya/10-2-7(1).pdf"}],"scriptFacets":["Ancient South Arabian"],"materialFacet":"Rock (unspecified)"},{"id":"murayghan-3","name":"Murayghān 3","siglum":"Murayghān 3","religion":"christian","dateLabel":"Mid-550s CE","dateNote":"Undated in the text; assigned to the mid-550s on historical grounds.","language":"Sabaic","script":"Ancient South Arabian (Musnad)","locality":"South Arabia (Ḥimyar)","site":"Biʾr Murayghān, southern Saudi Arabia","modernCountry":"Saudi Arabia","lat":19.06,"lon":43.79,"geoPrecision":"approximate","material":"Rock","support":"Rock face","dimensions":null,"transliteration":null,"translation":null,"provenance":"Christian · commissioned by Abraha of Ḥimyar (found in modern Saudi Arabia)","synopsis":"Abraha records returning from the land of Maʿadd having taken the Arabs of Maʿadd, Hagar and Khaṭṭ, Ṭayy, Yathrib and Guzām. The mention of Yathrib, the oasis that would become Medina, is the striking detail: it places the Christian king of Ḥimyar's authority over the very town where Muhammad would later establish his community, some seventy years earlier. It is a rare epigraphic attestation of a place otherwise known mainly from later Arabic literature.","textCount":1,"inLindstedt":false,"additionReason":"Ancient South Arabian material, excluded from Lindstedt's list by scope.","references":[{"citation":"Robin, Christian Julien. \"Ḥimyar, Aksūm, and Arabia Deserta in Late Antiquity.\" In Arabs and Empires before Islam, edited by Greg Fisher, 127–171. Oxford: Oxford University Press, 2015.","url":null},{"citation":"Robin, Christian Julien. \"Abraha et la reconquête de l'Arabie déserte.\" Jerusalem Studies in Arabic and Islam 39 (2012): 1–93.","url":null},{"citation":"Avanzini, Alessandra, ed. Corpus of South Arabian Inscriptions (DASI).","url":"https://dasi.cnr.it/"}],"scriptFacets":["Ancient South Arabian"],"materialFacet":"Rock (unspecified)"},{"id":"jabal-dhabub","name":"Jabal Dhabūb inscription","siglum":"Jabal Dhabūb (Ḏabūb)","religion":"monotheist","dateLabel":"Sixth century CE (early seventh at the latest)","dateNote":"Undated; an initial mid-seventh-century assignment was revised earlier on the basis of script and language.","language":"Late Sabaic","script":"Ancient South Arabian (minuscule Sabaic)","locality":"South Arabia (Ḥimyar)","site":"Jabal Dhabūb, al-Ḍāliʿ region","modernCountry":"Yemen","lat":13.7,"lon":44.73,"geoPrecision":"indicative","material":"Rock","support":"Rock facade near a summit","dimensions":"Two lines","transliteration":"bsm ʾlh rḥmn …","translation":"In the name of Allāh, the Raḥmān: have mercy upon us, O Lord of the heavens; satisfy us by means of your favour, and grant us the essence of it.","provenance":"Unclassified monotheist · Ḥimyarite kingdom (Yemen)","synopsis":"The earliest known epigraphic ancestor of the basmala, the formula that opens almost every chapter of the Qurʾān. Ahmad Al-Jallad's revised reading shows a two-part invocation combining the South Arabian divine name Raḥmān with the North Arabian Allāh, a fusion of two monotheistic vocabularies meeting in sixth-century Yemen. The writer may have been Jewish; the text is classed here as unclassified monotheist because nothing in it settles the question.","textCount":1,"inLindstedt":false,"additionReason":"Ancient South Arabian material, excluded from Lindstedt's list by scope; included for its direct bearing on the pre-history of the basmala.","references":[{"citation":"Al-Jallad, Ahmad. \"The Pre-Islamic Basmala: Reflections on Its First Epigraphic Attestation and Its Original Significance.\" Journal of the International Qurʾanic Studies Association (2022).","url":"https://almuslih.org/wp-content/uploads/Library/Jallad,%20A%20-%20The%20pre-Islamic%20Basmala.pdf"},{"citation":"Al-Hajj, Mohammed A., and Abdullah A. Faqʿas. \"A New Inscription from Jabal Dhabūb\" (in Arabic). 2018.","url":null},{"citation":"Al-Jallad, Ahmad. Ancient Allah: An Epigraphic Reconstruction. 2025.","url":"https://www.academia.edu/129395185/Al_Jallad_2025_Ancient_Allah_An_Epigraphic_Reconstruction"}],"scriptFacets":["Ancient South Arabian"],"materialFacet":"Rock (unspecified)"},{"id":"bariqi-robin-nait-1","name":"Bāriqī-Robin-Nāʿiṭ 1 (the 'elephants' inscription)","siglum":"Bāriqī-Robin-Nāʿiṭ 1","religion":"christian","dateLabel":"Reign of Abraha, c. 532/535–570 CE","dateNote":"Fragmentary and broken on both sides; dated by its reference to the reign of Abraha.","language":"Sabaic","script":"Ancient South Arabian (Musnad)","locality":"South Arabia (Ḥimyar)","site":"Nāʿiṭ, c. 50 km north of Ṣanʿāʾ","modernCountry":"Yemen","lat":15.75,"lon":44.05,"geoPrecision":"approximate","material":"Stone","support":"Fragment carved in relief; nine incomplete lines","dimensions":"Nine incomplete lines; broken at right and left","transliteration":null,"translation":null,"provenance":"Christian · Ḥimyarite kingdom (Yemen)","synopsis":"Published in 2025, after Lindstedt's list was compiled, this text shows how quickly the field moves. The fragment mentions King Abraha for the first time in the Yemeni highlands, bringing the number of texts from his reign to ten. A damaged word in line 5 may read 'elephant', which would connect it to the tradition of Abraha's elephant-borne expedition remembered in the Qurʾān, though the reading is uncertain and the editors present it as a hypothesis.","textCount":1,"inLindstedt":false,"additionReason":"Published in 2025, after Lindstedt's list; Ancient South Arabian material.","references":[{"citation":"al-Bāriqī, Zāhir ʿĀṭif, and Christian Julien Robin. \"Fragment of a Ḥimyarite Inscription Commissioned by King Abraha, with the Hypothetical Mention of Elephants.\" 2025.","url":"https://www.academia.edu/145725998/"},{"citation":"Robin, Christian Julien. \"Ḥimyar, Aksūm, and Arabia Deserta in Late Antiquity.\" In Arabs and Empires before Islam, edited by Greg Fisher, 127–171. Oxford: Oxford University Press, 2015.","url":null},{"citation":"Gajda, Iwona. \"Religions of Ancient South Arabia: From Polytheism to Monotheism.\" Arabian Archaeology and Epigraphy (2025).","url":"https://doi.org/10.1111/aae.70017"}],"scriptFacets":["Ancient South Arabian"],"materialFacet":"Stone"},{"id":"zabad","name":"Zebed inscription","siglum":"Zebed (Zabad) trilingual","religion":"christian","dateLabel":"512 CE","dateNote":"Explicitly dated: year 823 of the Seleucid era.","language":"Greek, Syriac and Old Arabic","script":"Greek, Syriac and Paleo-Arabic","locality":"Jordan & Syria","site":"Zebed, south-east of Aleppo","modernCountry":"Syria","lat":35.83,"lon":37.55,"geoPrecision":"approximate","material":"Limestone","support":"Lintel of the entrance portal of the martyrion of Saint Sergius; now in the Art & History Museum, Brussels","dimensions":null,"transliteration":null,"translation":"May God be mindful of Sergius son of ʿAbd Manāf, and Hani son of Māra al-Qays, and Sergius son of Saʿd, and Sitr and Sūraya.","provenance":"Christian · northern Syria","synopsis":"One of the small handful of pre-Islamic Arabic inscriptions from the Levant, and among the oldest securely dated: 512 CE. It stood over the door of a shrine to Saint Sergius, the soldier-saint especially venerated by Arab Christians. The three languages do different jobs (the Arabic lists Arab Christian donors), so the stone is a snapshot of a trilingual frontier society. Lindstedt notes that Jordan and Syria have yielded a number of such Christian Arabic texts but excludes them from his Saudi-focused list.","textCount":1,"inLindstedt":false,"additionReason":"Outside Lindstedt's Saudi Arabian scope; he notes explicitly that Jordan has bequeathed Christian inscriptions of this era that his map omits.","references":[{"citation":"Fisher, Greg. Rome, Persia, and Arabia: Shaping the Middle East from Pompey to Muhammad. London: Routledge, 2020.","url":null},{"citation":"Robin, Christian Julien. \"La réforme de l'écriture arabe à l'époque du califat médinois.\" Mélanges de l'Université Saint-Joseph 59 (2006): 319–364.","url":null},{"citation":"Hoyland, Robert G. \"Epigraphy and the Linguistic Background to the Qurʾān.\" In The Qurʾān in Its Historical Context, edited by Gabriel S. Reynolds, 51–69. London: Routledge, 2008.","url":null}],"scriptFacets":["Paleo-Arabic","Syriac","Greek"],"materialFacet":"Limestone"},{"id":"jabal-usays","name":"Jabal Usays inscription","siglum":"Jabal Usays (Jabal Says)","religion":"christian","dateLabel":"528/529 CE","dateNote":"Explicitly dated: year 423 of the era of the Province of Arabia.","language":"Old Arabic","script":"Paleo-Arabic","locality":"Jordan & Syria","site":"Jabal Usays, in the basalt desert south-east of Damascus","modernCountry":"Syria","lat":33.06,"lon":37.16,"geoPrecision":"approximate","material":"Basalt","support":"Rock face","dimensions":null,"transliteration":null,"translation":"I am Ruqaym son of Muʿarrif al-Awsī. Al-Ḥārith the king sent me to Usays, as a garrison, in the year 423.","provenance":"Christian · southern Syria","synopsis":"A soldier's record of his posting, dated 528/529 and naming al-Ḥārith the king: al-Ḥārith ibn Jabala, the Jafnid (Ghassānid) phylarch who governed the Arab frontier on behalf of the Christian Roman empire. It is one of only three known sixth-century uses of the Arabic script in Syria, alongside Zebed and Ḥarrān. The Jafnids were staunchly Christian, and their patronage is a large part of why Arabic writing survives at all from this region and century.","textCount":1,"inLindstedt":false,"additionReason":"Outside Lindstedt's Saudi Arabian scope.","references":[{"citation":"Fisher, Greg. Rome, Persia, and Arabia: Shaping the Middle East from Pompey to Muhammad. London: Routledge, 2020.","url":null},{"citation":"Robin, Christian Julien. \"La réforme de l'écriture arabe à l'époque du califat médinois.\" Mélanges de l'Université Saint-Joseph 59 (2006): 319–364.","url":null},{"citation":"Fisher, Greg, ed. Arabs and Empires before Islam. Oxford: Oxford University Press, 2015.","url":null}],"scriptFacets":["Paleo-Arabic"],"materialFacet":"Basalt"},{"id":"harran-al-laja","name":"Ḥarrān al-Lajāʾ inscription","siglum":"Ḥarrān (Lajāʾ) bilingual","religion":"christian","dateLabel":"568 CE","dateNote":"Explicitly dated: year 463 of the era of the Province of Arabia.","language":"Greek and Old Arabic","script":"Greek and Paleo-Arabic","locality":"Jordan & Syria","site":"Ḥarrān, in the Lajāʾ, south of Damascus (as-Suwaydāʾ governorate)","modernCountry":"Syria","lat":32.72,"lon":36.63,"geoPrecision":"approximate","material":"Basalt","support":"Building inscription from a martyrion","dimensions":null,"transliteration":null,"translation":"I, Sharaḥīl son of Ẓālim, built this martyrion in the year 463, one year after the destruction of Khaybar.","provenance":"Christian · southern Syria","synopsis":"A Greek–Arabic bilingual recording the construction of a shrine to Saint John by an Arab phylarch. Its most debated line dates the building by reference to Khaybar, the Ḥijāzī oasis with a well-known Jewish population. Michael Macdonald reads it as a rebellion by Khaybar rather than an expedition against it. Either way, a builder in Syria dating his church by an event in the Ḥijāz shows that the two regions belonged to a single connected world.","textCount":1,"inLindstedt":false,"additionReason":"Outside Lindstedt's Saudi Arabian scope.","references":[{"citation":"Fisher, Greg. Rome, Persia, and Arabia: Shaping the Middle East from Pompey to Muhammad. London: Routledge, 2020.","url":null},{"citation":"Macdonald, Michael C. A. \"Arabs, Arabias, and Arabic before Late Antiquity.\" Topoi 16 (2009): 277–332.","url":null},{"citation":"Robin, Christian Julien. \"La réforme de l'écriture arabe à l'époque du califat médinois.\" Mélanges de l'Université Saint-Joseph 59 (2006): 319–364.","url":null}],"scriptFacets":["Paleo-Arabic","Greek"],"materialFacet":"Basalt"},{"id":"umm-al-jimal-paleoarabic","name":"Umm al-Jimāl Paleo-Arabic inscription","siglum":"Umm al-Jimāl (the ʾUlayh inscription)","religion":"monotheist","dateLabel":"Fifth or sixth century CE","dateNote":"Undated; Littmann favoured the sixth century, Bellamy the fifth.","language":"Old Arabic","script":"Paleo-Arabic","locality":"Jordan & Syria","site":"Umm al-Jimāl, Ḥawrān region, northern Jordan (the 'Double Church')","modernCountry":"Jordan","lat":32.33,"lon":36.37,"geoPrecision":"approximate","material":"Basalt","support":"Pillar base in the north part of the Double Church","dimensions":null,"transliteration":null,"translation":"God, [grant] pardon to ʾUlayh son of ʿUbayd, secretary of al-ʿUbayd, chief of the Banū ʿAmr; may he who reads it take notice. (Littmann's reading; Bellamy proposed a substantially different text.)","provenance":"Unclassified monotheist · northern Jordan","synopsis":"Found on a pillar base in a church at Umm al-Jimāl, and classified here as unclassified monotheist precisely because the readings diverge so sharply: Littmann's version is a prayer to God, Bellamy's a secular memorial with a curse on anyone who effaces it. The stone is pitted and hard to read, and scholars have said plainly that no fully adequate reading is possible without new photographs. It is a useful reminder of how much epigraphic interpretation rests on contested readings of damaged surfaces.","textCount":1,"inLindstedt":false,"additionReason":"Outside Lindstedt's Saudi Arabian scope; included to represent the Jordanian material he notes but omits.","references":[{"citation":"Littmann, Enno. Semitic Inscriptions. Publications of the Princeton University Archaeological Expeditions to Syria, Division IV. Leiden: Brill, 1914–1949.","url":null},{"citation":"Bellamy, James A. \"Two Pre-Islamic Arabic Inscriptions Revised: Jabal Ramm and Umm al-Jimāl.\" Journal of the American Oriental Society 108, no. 3 (1988): 369–378.","url":null},{"citation":"Macdonald, Michael C. A. \"Arabs, Arabias, and Arabic before Late Antiquity.\" Topoi 16 (2009): 277–332.","url":null}],"scriptFacets":["Paleo-Arabic"],"materialFacet":"Basalt"},{"id":"wadi-al-shuwayti-mundhir","name":"Wādī al-Shuwayṭī inscription (al-Mundhir the king)","siglum":"Al-Jallad, al-Manaser & Fisher 2026","religion":"monotheist","dateLabel":"Reign of al-Mundhir III, c. 569–581 CE","dateNote":"Dated internally by reference to the reign of a king called ʾmndr, identified by the editors as the Jafnid ruler al-Mundhir III ibn al-Ḥārith.","language":"Old Arabic","script":"Paleo-Arabic","locality":"Jordan & Syria","site":"Wādī al-Shuwayṭī, north-eastern Jordanian Ḥarrah","modernCountry":"Jordan","lat":32.3,"lon":37.5,"geoPrecision":"indicative","material":"Basalt","support":"Rock face","dimensions":null,"transliteration":null,"translation":null,"provenance":"Unclassified monotheist · north-eastern Jordan","synopsis":"Published in January 2026, after Lindstedt's list, this newly discovered Paleo-Arabic text is dated by the reign of a king named ʾmndr, whom the editors identify as al-Mundhir III, the Christian Jafnid ruler of the Arab frontier. It is a significant addition because dated Paleo-Arabic inscriptions are rare, and because it shows Arabs in the Jordanian basalt desert reckoning time by their own kings rather than by imperial eras.","textCount":1,"inLindstedt":false,"additionReason":"Published in January 2026, after Lindstedt's list was compiled; also outside his Saudi Arabian scope.","references":[{"citation":"Al-Jallad, Ahmad, Ali al-Manaser, and Greg Fisher. \"A Dated Paleo-Arabic Inscription Mentioning Al-Mundhir (ʾmndr) the King.\" Arabian Archaeology and Epigraphy (2026).","url":"https://doi.org/10.1111/aae.70013"},{"citation":"Fisher, Greg, ed. Arabs and Empires before Islam. Oxford: Oxford University Press, 2015.","url":null},{"citation":"Fisher, Greg. Rome, Persia, and Arabia: Shaping the Middle East from Pompey to Muhammad. London: Routledge, 2020.","url":null}],"scriptFacets":["Paleo-Arabic"],"materialFacet":"Basalt"},{"id":"jubail-church","name":"Jubail church","siglum":"Jubail church (al-Jubayl)","religion":"christian-context","dateLabel":"c. fourth–sixth century CE (debated)","dateNote":"Material culture, not a datable text. The dating of the building is debated and rests on architecture and comparanda rather than an inscription.","language":"None (architectural remains)","script":"None","locality":"Eastern Arabia & the Gulf","site":"Jubail, Eastern Province","modernCountry":"Saudi Arabia","lat":27.02,"lon":49.66,"geoPrecision":"approximate","material":"Stone and plaster","support":"Church building with carved crosses","dimensions":null,"transliteration":null,"translation":null,"provenance":"Christian (material culture) · eastern Arabia (Saudi Arabia)","synopsis":"A ruined church building in eastern Saudi Arabia, decorated with crosses in the manner of the Church of the East. It is included here as context rather than as an inscription: there is no datable text, and the chronology is disputed. Sites like this one document the Christian province the Syriac sources call Bēt Qaṭrāyē, a well-organised church on the Gulf coast that the inscription-based map of inland Arabia does not capture.","textCount":1,"inLindstedt":false,"additionReason":"Contextual Christian material culture from eastern Arabia, outside Lindstedt's inscription-based scope. Flagged as a distinct evidence class.","references":[{"citation":"Bonnéric, Julie. \"Archaeological Evidence of an Early Islamic Monastery in the Centre of al-Quṣūr (Failaka Island, Kuwait).\" Arabian Archaeology and Epigraphy 32, no. 1 (2021): 153–171.","url":"https://doi.org/10.1111/aae.12182"},{"citation":"Carter, Robert. \"Christianity in the Gulf during the First Centuries of Islam.\" Arabian Archaeology and Epigraphy 19, no. 1 (2008): 71–108.","url":null},{"citation":"Fisher, Greg, ed. Arabs and Empires before Islam. Oxford: Oxford University Press, 2015.","url":null}],"scriptFacets":["Not applicable"],"materialFacet":"Stone & plaster"},{"id":"sir-bani-yas","name":"Sir Bani Yas monastery","siglum":"Sir Bani Yas","religion":"christian-context","dateLabel":"c. mid-seventh–eighth century CE","dateNote":"Material culture, not a datable text. Plaster friezes are dated to the mid-seventh to eighth century, i.e. probably already the early Islamic period.","language":"None (architectural remains)","script":"None","locality":"Eastern Arabia & the Gulf","site":"Sir Bani Yas island, Abu Dhabi","modernCountry":"United Arab Emirates","lat":24.32,"lon":52.58,"geoPrecision":"approximate","material":"Stone and moulded plaster","support":"Monastery complex with a church; plaster friezes bearing crosses","dimensions":null,"transliteration":null,"translation":null,"provenance":"Christian (material culture) · Gulf coast (United Arab Emirates)","synopsis":"The best-known Church of the East monastery in the Gulf, with a church whose plaster friezes carry crosses and vine-and-palm scrolls in a recognisably East Syrian style. Its dating matters for honesty's sake: the decoration points to the mid-seventh and eighth centuries, which is after the rise of Islam rather than before it. It belongs on this map as evidence that Christian communities persisted and even built in Arabia across the transition, not as evidence for the fifth and sixth centuries.","textCount":1,"inLindstedt":false,"additionReason":"Contextual Christian material culture from eastern Arabia, outside Lindstedt's inscription-based scope. Flagged as a distinct evidence class with post-600 dating.","references":[{"citation":"Carter, Robert. \"Christianity in the Gulf during the First Centuries of Islam.\" Arabian Archaeology and Epigraphy 19, no. 1 (2008): 71–108.","url":null},{"citation":"King, Geoffrey R. D. \"A Nestorian Monastic Settlement on the Island of Ṣīr Banī Yās, Abu Dhabi.\" Bulletin of the School of Oriental and African Studies 60, no. 2 (1997): 221–235.","url":null},{"citation":"Bonnéric, Julie. \"Archaeological Evidence of an Early Islamic Monastery in the Centre of al-Quṣūr (Failaka Island, Kuwait).\" Arabian Archaeology and Epigraphy 32, no. 1 (2021): 153–171.","url":"https://doi.org/10.1111/aae.12182"}],"scriptFacets":["Not applicable"],"materialFacet":"Stone & plaster"},{"id":"siniyah-island","name":"Siniyah Island monastery","siglum":"Sīnīya Island, Umm al-Quwain","religion":"christian-context","dateLabel":"c. 534–656 CE (radiocarbon), flourishing to the mid-eighth century","dateNote":"Material culture, not a datable text. Radiocarbon samples from the foundations fall between 534 and 656 CE.","language":"None (architectural remains)","script":"None","locality":"Eastern Arabia & the Gulf","site":"Sīnīya Island, Umm al-Quwain","modernCountry":"United Arab Emirates","lat":25.59,"lon":55.55,"geoPrecision":"approximate","material":"Stone and plaster","support":"Monastery complex: church, refectory, cisterns and monastic cells","dimensions":null,"transliteration":null,"translation":null,"provenance":"Christian (material culture) · Gulf coast (United Arab Emirates)","synopsis":"Discovered in 2022 and among the most important recent finds in Arabian archaeology. Radiocarbon dates from the foundations fall between 534 and 656 CE, which means the monastery was founded before Islam and continued in use afterwards. Its plan (church, refectory, cisterns, individual cells) shows a fully developed monastic institution on the Gulf coast, evidence of the organised Christianity of Bēt Qaṭrāyē that the inland inscription record does not reach.","textCount":1,"inLindstedt":false,"additionReason":"Contextual Christian material culture, discovered 2022 and outside Lindstedt's inscription-based scope. Flagged as a distinct evidence class.","references":[{"citation":"Power, Timothy, et al. \"A Newly Discovered Late Antique Monastery and Islamic Town on Sīnīya Island, Umm al-Quwain.\" Arabian Archaeology and Epigraphy (2023).","url":"https://www.academia.edu/106784296/"},{"citation":"Carter, Robert. \"Christianity in the Gulf during the First Centuries of Islam.\" Arabian Archaeology and Epigraphy 19, no. 1 (2008): 71–108.","url":null},{"citation":"Bonnéric, Julie. \"Archaeological Evidence of an Early Islamic Monastery in the Centre of al-Quṣūr (Failaka Island, Kuwait).\" Arabian Archaeology and Epigraphy 32, no. 1 (2021): 153–171.","url":"https://doi.org/10.1111/aae.12182"}],"scriptFacets":["Not applicable"],"materialFacet":"Stone & plaster"},{"id":"al-qusur-failaka","name":"Al-Quṣūr church and monastery","siglum":"Al-Quṣūr, Failaka Island","religion":"christian-context","dateLabel":"c. sixth–ninth century CE (debated)","dateNote":"Material culture, not a datable text. Recent work argues the central complex functioned as a monastery into the early Islamic period.","language":"None (architectural remains)","script":"None","locality":"Eastern Arabia & the Gulf","site":"Al-Quṣūr, Failaka Island","modernCountry":"Kuwait","lat":29.43,"lon":48.33,"geoPrecision":"approximate","material":"Stone and plaster","support":"Church, refectory and monastic cell; plaster crosses","dimensions":null,"transliteration":null,"translation":null,"provenance":"Christian (material culture) · Gulf coast (Kuwait)","synopsis":"Excavated by the French mission to Kuwait, al-Quṣūr yielded a church, a large refectory and what is probably a monk's cell, enough for the excavators to identify at least the central part of the site as a monastery. Julie Bonnéric's work argues it remained in use well into the early Islamic centuries. Along with Sir Bani Yas, Siniyah and Samahij, it maps a Christian institutional network along the whole Gulf littoral.","textCount":1,"inLindstedt":false,"additionReason":"Contextual Christian material culture from eastern Arabia, outside Lindstedt's inscription-based scope. Flagged as a distinct evidence class.","references":[{"citation":"Bonnéric, Julie. \"Archaeological Evidence of an Early Islamic Monastery in the Centre of al-Quṣūr (Failaka Island, Kuwait).\" Arabian Archaeology and Epigraphy 32, no. 1 (2021): 153–171.","url":"https://doi.org/10.1111/aae.12182"},{"citation":"Carter, Robert. \"Christianity in the Gulf during the First Centuries of Islam.\" Arabian Archaeology and Epigraphy 19, no. 1 (2008): 71–108.","url":null},{"citation":"Fisher, Greg, ed. Arabs and Empires before Islam. Oxford: Oxford University Press, 2015.","url":null}],"scriptFacets":["Not applicable"],"materialFacet":"Stone & plaster"},{"id":"samahij-bahrain","name":"Samahij Christian building","siglum":"Samahij (Meshmahig)","religion":"christian-context","dateLabel":"c. mid-fourth–mid-eighth century CE (radiocarbon)","dateNote":"Material culture, not a datable text. Radiocarbon dating indicates occupation from the mid-fourth to the mid-eighth century.","language":"None (architectural remains)","script":"None","locality":"Eastern Arabia & the Gulf","site":"Samahij, Muharraq","modernCountry":"Bahrain","lat":26.25,"lon":50.63,"geoPrecision":"approximate","material":"Stone and plaster","support":"Eight-room building, probably the residence of the Bishop of Meshmahig","dimensions":null,"transliteration":null,"translation":null,"provenance":"Christian (material culture) · Gulf coast (Bahrain)","synopsis":"Excavated by a Bahraini–British team and announced in 2024 as the earliest Christian structure known in the Gulf. Radiocarbon places its occupation between the mid-fourth and mid-eighth centuries, and the excavators interpret it as the residence of the Bishop of Meshmahig, a see known from Syriac church records. The building appears to have been abandoned as Islam spread locally, giving an unusually direct archaeological picture of the transition.","textCount":1,"inLindstedt":false,"additionReason":"Contextual Christian material culture, announced 2024 and outside Lindstedt's inscription-based scope. Flagged as a distinct evidence class.","references":[{"citation":"Insoll, Timothy, and Salman Al Mahari. Excavations at Samahij, Bahrain. University of Exeter / Bahrain Authority for Culture and Antiquities, 2024.","url":"https://news.exeter.ac.uk/faculty-of-humanities-arts-and-social-sciences/archaeologists-discover-the-first-christian-building-in-bahrain/"},{"citation":"Carter, Robert. \"Christianity in the Gulf during the First Centuries of Islam.\" Arabian Archaeology and Epigraphy 19, no. 1 (2008): 71–108.","url":null},{"citation":"Bonnéric, Julie. \"Archaeological Evidence of an Early Islamic Monastery in the Centre of al-Quṣūr (Failaka Island, Kuwait).\" Arabian Archaeology and Epigraphy 32, no. 1 (2021): 153–171.","url":"https://doi.org/10.1111/aae.12182"}],"scriptFacets":["Not applicable"],"materialFacet":"Stone & plaster"}]};
